113→// ReadSession reads a session from Claude's storage (JSONL transcript file).
114→// The session data is stored in NativeData as raw JSONL bytes.
115→// ModifiedFiles is computed by parsing the transcript.
116→func (c *ClaudeCodeAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
117→	if input.SessionRef == "" {
118→		return nil, errors.New("session reference (transcript path) is required")
119→	}
120→
121→	// Read the raw JSONL file
122→	data, err := os.ReadFile(input.SessionRef)
123→	if err != nil {
124→		return nil, fmt.Errorf("failed to read transcript: %w", err)
125→	}
126→
127→	// Parse to extract computed fields
128→	lines, err := transcript.ParseFromBytes(data)
129→	if err != nil {
130→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
131→	}
132→
133→	return &agent.AgentSession{
134→		SessionID:     input.SessionID,
135→		AgentName:     c.Name(),
136→		SessionRef:    input.SessionRef,
137→		StartTime:     time.Now(),
138→		NativeData:    data,
139→		ModifiedFiles: ExtractModifiedFiles(lines),
140→	}, nil
141→}
