143→// WriteSession writes a session to Claude's storage (JSONL transcript file).
144→// Uses the NativeData field which contains raw JSONL bytes.
145→// The session must have been created by Claude Code (AgentName check).
146→func (c *ClaudeCodeAgent) WriteSession(_ context.Context, session *agent.AgentSession) error {
147→	if session == nil {
148→		return errors.New("session is nil")
149→	}
150→
151→	// Verify this session belongs to Claude Code
152→	if session.AgentName != "" && session.AgentName != c.Name() {
153→		return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, c.Name())
154→	}
155→
156→	if session.SessionRef == "" {
157→		return errors.New("session reference (transcript path) is required")
158→	}
159→
160→	if len(session.NativeData) == 0 {
161→		return errors.New("session has no native data to write")
162→	}
163→
164→	// Write the raw JSONL data
165→	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
166→		return fmt.Errorf("failed to write transcript: %w", err)
167→	}
168→
169→	return nil
170→}
