179→// GetLastUserPrompt extracts the last user prompt from the session.
180→// Requires NativeData to be populated (call ReadSession first).
181→func (c *ClaudeCodeAgent) GetLastUserPrompt(session *agent.AgentSession) string {
182→	if session == nil || len(session.NativeData) == 0 {
183→		return ""
184→	}
185→
186→	lines, err := transcript.ParseFromBytes(session.NativeData)
187→	if err != nil {
188→		return ""
189→	}
190→
191→	return ExtractLastUserPrompt(lines)
