194→// TruncateAtUUID returns a new session truncated at the given UUID (inclusive).
195→// This is used for rewind operations to restore transcript state.
196→// Requires NativeData to be populated.
197→func (c *ClaudeCodeAgent) TruncateAtUUID(session *agent.AgentSession, uuid string) (*agent.AgentSession, error) {
198→	if session == nil {
199→		return nil, errors.New("session is nil")
200→	}
201→
202→	if len(session.NativeData) == 0 {
203→		return nil, errors.New("session has no native data")
204→	}
205→
206→	if uuid == "" {
207→		// No truncation needed, return copy
208→		return &agent.AgentSession{
209→			SessionID:     session.SessionID,
210→			AgentName:     session.AgentName,
211→			RepoPath:      session.RepoPath,
212→			SessionRef:    session.SessionRef,
213→			StartTime:     session.StartTime,
214→			NativeData:    session.NativeData,
215→			ModifiedFiles: session.ModifiedFiles,
216→		}, nil
217→	}
218→
219→	// Parse, truncate, re-serialize
220→	lines, err := transcript.ParseFromBytes(session.NativeData)
221→	if err != nil {
222→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
223→	}
224→
225→	truncated := TruncateAtUUID(lines, uuid)
226→
227→	newData, err := SerializeTranscript(truncated)
228→	if err != nil {
229→		return nil, fmt.Errorf("failed to serialize truncated transcript: %w", err)
230→	}
231→
232→	return &agent.AgentSession{
233→		SessionID:     session.SessionID,
234→		AgentName:     session.AgentName,
235→		RepoPath:      session.RepoPath,
236→		SessionRef:    session.SessionRef,
237→		StartTime:     session.StartTime,
238→		NativeData:    newData,
239→		ModifiedFiles: ExtractModifiedFiles(truncated),
240→	}, nil
241→}
