276→// TranscriptAnalyzer interface implementation
277→
278→// GetTranscriptPosition returns the current line count of a Claude Code transcript.
279→// Claude Code uses JSONL format, so position is the number of lines.
280→// This is a lightweight operation that only counts lines without parsing JSON.
281→// Uses bufio.Reader to handle arbitrarily long lines (no size limit).
282→// Returns 0 if the file doesn't exist or is empty.
283→func (c *ClaudeCodeAgent) GetTranscriptPosition(path string) (int, error) {
284→	if path == "" {
285→		return 0, nil
286→	}
287→
288→	file, err := os.Open(path) //nolint:gosec // Path comes from Claude Code transcript location
289→	if err != nil {
290→		if os.IsNotExist(err) {
291→			return 0, nil
292→		}
293→		return 0, fmt.Errorf("failed to open transcript file: %w", err)
294→	}
295→	defer file.Close()
296→
297→	reader := bufio.NewReader(file)
298→	lineCount := 0
299→
300→	for {
301→		line, err := reader.ReadBytes('\n')
302→		if err != nil {
303→			if err == io.EOF {
304→				if len(line) > 0 {
305→					lineCount++ // Count final line without trailing newline
306→				}
307→				break
308→			}
309→			return 0, fmt.Errorf("failed to read transcript: %w", err)
310→		}
311→		lineCount++
312→	}
313→
314→	return lineCount, nil
315→}
