317→// ExtractModifiedFilesFromOffset extracts files modified since a given line number.
318→// For Claude Code (JSONL format), offset is the starting line number.
319→// Uses bufio.Reader to handle arbitrarily long lines (no size limit).
320→// Returns:
321→//   - files: list of file paths modified by Claude (from Write/Edit tools)
322→//   - currentPosition: total number of lines in the file
323→//   - error: any error encountered during reading
324→func (c *ClaudeCodeAgent) ExtractModifiedFilesFromOffset(path string, startOffset int) (files []string, currentPosition int, err error) {
325→	if path == "" {
326→		return nil, 0, nil
327→	}
328→
329→	file, openErr := os.Open(path) //nolint:gosec // Path comes from Claude Code transcript location
330→	if openErr != nil {
331→		return nil, 0, fmt.Errorf("failed to open transcript file: %w", openErr)
332→	}
333→	defer file.Close()
334→
335→	reader := bufio.NewReader(file)
336→	var lines []TranscriptLine
337→	lineNum := 0
338→
339→	for {
340→		lineData, readErr := reader.ReadBytes('\n')
341→		if readErr != nil && readErr != io.EOF {
342→			return nil, 0, fmt.Errorf("failed to read transcript: %w", readErr)
343→		}
344→
345→		if len(lineData) > 0 {
346→			lineNum++
347→			if lineNum > startOffset {
348→				var line TranscriptLine
349→				if parseErr := json.Unmarshal(lineData, &line); parseErr == nil {
350→					lines = append(lines, line)
351→				}
352→				// Skip malformed lines silently
353→			}
354→		}
355→
356→		if readErr == io.EOF {
357→			break
358→		}
359→	}
360→
361→	return ExtractModifiedFiles(lines), lineNum, nil
362→}
