364→// ChunkTranscript splits a JSONL transcript at line boundaries.
365→// Claude Code uses JSONL format (one JSON object per line), so chunking
366→// is done at newline boundaries to preserve message integrity.
367→func (c *ClaudeCodeAgent) ChunkTranscript(_ context.Context, content []byte, maxSize int) ([][]byte, error) {
368→	chunks, err := agent.ChunkJSONL(content, maxSize)
369→	if err != nil {
370→		return nil, fmt.Errorf("failed to chunk JSONL transcript: %w", err)
371→	}
372→	return chunks, nil
373→}
