375→// ReassembleTranscript concatenates JSONL chunks with newlines.
376→//
377→
378→func (c *ClaudeCodeAgent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
379→	return agent.ReassembleJSONL(chunks), nil
380→}
