412→func hookCommandExists(matchers []ClaudeHookMatcher, command string) bool {
413→	for _, matcher := range matchers {
414→		for _, hook := range matcher.Hooks {
415→			if hook.Command == command {
416→				return true
417→			}
418→		}
419→	}
420→	return false
421→}
422→
423→func hookCommandExistsWithMatcher(matchers []ClaudeHookMatcher, matcherName, command string) bool {
424→	for _, matcher := range matchers {
425→		if matcher.Matcher == matcherName {
426→			for _, hook := range matcher.Hooks {
427→				if hook.Command == command {
428→					return true
429→				}
430→			}
431→		}
432→	}
433→	return false
434→}
435→
436→func addHookToMatcher(matchers []ClaudeHookMatcher, matcherName, command string) []ClaudeHookMatcher {
437→	entry := ClaudeHookEntry{
438→		Type:    "command",
439→		Command: command,
440→	}
441→
442→	// If no matcher name, add to a matcher with empty string
443→	if matcherName == "" {
444→		for i, matcher := range matchers {
445→			if matcher.Matcher == "" {
446→				matchers[i].Hooks = append(matchers[i].Hooks, entry)
447→				return matchers
448→			}
449→		}
450→		return append(matchers, ClaudeHookMatcher{
451→			Matcher: "",
452→			Hooks:   []ClaudeHookEntry{entry},
453→		})
454→	}
455→
456→	// Find or create matcher with the given name
457→	for i, matcher := range matchers {
458→		if matcher.Matcher == matcherName {
459→			matchers[i].Hooks = append(matchers[i].Hooks, entry)
460→			return matchers
461→		}
462→	}
463→
464→	return append(matchers, ClaudeHookMatcher{
465→		Matcher: matcherName,
466→		Hooks:   []ClaudeHookEntry{entry},
467→	})
468→}
