470→// isEntireHook checks if a command is an Entire hook (old or new format)
471→func isEntireHook(command string) bool {
472→	for _, prefix := range entireHookPrefixes {
473→		if strings.HasPrefix(command, prefix) {
474→			return true
475→		}
476→	}
477→	return false
478→}
479→
480→// removeEntireHooks removes all Entire hooks from a list of matchers (for simple hooks like Stop)
481→func removeEntireHooks(matchers []ClaudeHookMatcher) []ClaudeHookMatcher {
482→	result := make([]ClaudeHookMatcher, 0, len(matchers))
483→	for _, matcher := range matchers {
484→		filteredHooks := make([]ClaudeHookEntry, 0, len(matcher.Hooks))
485→		for _, hook := range matcher.Hooks {
486→			if !isEntireHook(hook.Command) {
487→				filteredHooks = append(filteredHooks, hook)
488→			}
489→		}
490→		// Only keep the matcher if it has hooks remaining
491→		if len(filteredHooks) > 0 {
492→			matcher.Hooks = filteredHooks
493→			result = append(result, matcher)
494→		}
495→	}
496→	return result
497→}
