499→// removeEntireHooksFromMatchers removes Entire hooks from tool-use matchers (PreToolUse, PostToolUse)
500→// This handles the nested structure where hooks are grouped by tool matcher (e.g., "Task", "TodoWrite")
501→func removeEntireHooksFromMatchers(matchers []ClaudeHookMatcher) []ClaudeHookMatcher {
502→	// Same logic as removeEntireHooks - both work on the same structure
503→	return removeEntireHooks(matchers)
504→}
