 90→// ResolveSessionFile returns the path to a Gemini session file.
 91→// Gemini names files as session-<date>-<shortid>.json where shortid is the first 8 chars
 92→// of the session UUID. This searches for an existing file matching the pattern, falling
 93→// back to constructing a filename matching Gemini's convention if no match is found.
 94→func (g *GeminiCLIAgent) ResolveSessionFile(sessionDir, agentSessionID string) string {
 95→	// Try to find existing file matching Gemini's naming convention:
 96→	// session-*-<first8chars>.json
 97→	shortID := agentSessionID
 98→	if len(shortID) > 8 {
 99→		shortID = shortID[:8]
100→	}
101→
102→	pattern := filepath.Join(sessionDir, "session-*-"+shortID+".json")
103→	matches, err := filepath.Glob(pattern)
104→	if err == nil && len(matches) > 0 {
105→		// Return the most recent match (last alphabetically, since date is in the name)
106→		return matches[len(matches)-1]
107→	}
108→
109→	// Fallback: construct filename matching Gemini's convention: session-<timestamp>-<id[:8]>.json
110→	timestamp := time.Now().UTC().Format("2006-01-02T15-04")
111→	return filepath.Join(sessionDir, "session-"+timestamp+"-"+shortID+".json")
112→}
