162→// WriteSession writes a session to Gemini's storage (JSON transcript file).
163→// Uses the NativeData field which contains raw JSON bytes.
164→func (g *GeminiCLIAgent) WriteSession(_ context.Context, session *agent.AgentSession) error {
165→	if session == nil {
