169→	// Verify this session belongs to Gemini CLI
170→	if session.AgentName != "" && session.AgentName != g.Name() {
171→		return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, g.Name())
172→	}
173→
174→	if session.SessionRef == "" {
175→		return errors.New("session reference (transcript path) is required")
176→	}
177→
178→	if len(session.NativeData) == 0 {
179→		return errors.New("session has no native data to write")
180→	}
