204→// GetTranscriptPosition returns the current message count of a Gemini transcript.
205→// Gemini uses JSON format with a messages array, so position is the message count.
206→// Returns 0 if the file doesn't exist or is empty.
207→func (g *GeminiCLIAgent) GetTranscriptPosition(path string) (int, error) {
208→	if path == "" {
209→		return 0, nil
210→	}
211→
212→	data, err := os.ReadFile(path) //nolint:gosec // Reading from controlled transcript path
213→	if err != nil {
214→		if os.IsNotExist(err) {
215→			return 0, nil
216→		}
217→		return 0, fmt.Errorf("failed to read transcript: %w", err)
218→	}
219→
220→	if len(data) == 0 {
221→		return 0, nil
222→	}
223→
224→	transcript, err := ParseTranscript(data)
225→	if err != nil {
226→		return 0, fmt.Errorf("failed to parse transcript: %w", err)
227→	}
228→
229→	return len(transcript.Messages), nil
230→}
