232→// ExtractModifiedFilesFromOffset extracts files modified since a given message index.
233→// For Gemini (JSON format), offset is the starting message index.
234→// Returns:
235→//   - files: list of file paths modified by Gemini (from Write/Edit tools)
236→//   - currentPosition: total number of messages in the transcript
237→//   - error: any error encountered during reading
238→func (g *GeminiCLIAgent) ExtractModifiedFilesFromOffset(path string, startOffset int) (files []string, currentPosition int, err error) {
239→	if path == "" {
240→		return nil, 0, nil
241→	}
242→
243→	data, readErr := os.ReadFile(path) //nolint:gosec // Reading from controlled transcript path
244→	if readErr != nil {
245→		if os.IsNotExist(readErr) {
246→			return nil, 0, nil
247→		}
248→		return nil, 0, fmt.Errorf("failed to read transcript: %w", readErr)
249→	}
250→
251→	if len(data) == 0 {
252→		return nil, 0, nil
253→	}
254→
255→	transcript, parseErr := ParseTranscript(data)
256→	if parseErr != nil {
257→		return nil, 0, parseErr
258→	}
259→
260→	totalMessages := len(transcript.Messages)
261→
262→	// Extract files from messages starting at startOffset
263→	fileSet := make(map[string]bool)
264→	for i := startOffset; i < len(transcript.Messages); i++ {
265→		msg := transcript.Messages[i]
266→		// Only process gemini messages (assistant messages)
267→		if msg.Type != MessageTypeGemini {
268→			continue
269→		}
270→
271→		// Process tool calls in this message
272→		for _, toolCall := range msg.ToolCalls {
273→			// Check if it's a file modification tool
274→			isModifyTool := false
275→			for _, name := range FileModificationTools {
276→				if toolCall.Name == name {
277→					isModifyTool = true
278→					break
279→				}
280→			}
281→
282→			if !isModifyTool {
283→				continue
284→			}
285→
286→			// Extract file path from args map
287→			var file string
288→			if fp, ok := toolCall.Args["file_path"].(string); ok && fp != "" {
289→				file = fp
290→			} else if p, ok := toolCall.Args["path"].(string); ok && p != "" {
291→				file = p
292→			} else if fn, ok := toolCall.Args["filename"].(string); ok && fn != "" {
293→				file = fn
294→			}
295→
296→			if file != "" && !fileSet[file] {
297→				fileSet[file] = true
298→				files = append(files, file)
299→			}
300→		}
301→	}
302→
303→	return files, totalMessages, nil
304→}
305→
306→// ChunkTranscript splits a Gemini JSON transcript by distributing messages across chunks.
307→// Gemini uses JSON format with a {"messages": [...]} structure, so chunking splits
308→// the messages array while preserving the JSON structure in each chunk.
309→func (g *GeminiCLIAgent) ChunkTranscript(ctx context.Context, content []byte, maxSize int) ([][]byte, error) {
310→	var transcript GeminiTranscript
311→	if err := json.Unmarshal(content, &transcript); err != nil {
312→		// Fall back to JSONL chunking if not valid Gemini JSON
313→		chunks, chunkErr := agent.ChunkJSONL(content, maxSize)
314→		if chunkErr != nil {
315→			return nil, fmt.Errorf("failed to chunk as JSONL: %w", chunkErr)
316→		}
317→		return chunks, nil
318→	}
319→
320→	if len(transcript.Messages) == 0 {
321→		return [][]byte{content}, nil
322→	}
323→
324→	var chunks [][]byte
325→	var currentMessages []GeminiMessage
326→	currentSize := len(`{"messages":[]}`) // Base JSON structure size
327→
328→	for i, msg := range transcript.Messages {
329→		// Marshal message to get its size
330→		msgBytes, err := json.Marshal(msg)
331→		if err != nil {
332→			logging.Warn(ctx, "failed to marshal Gemini message during chunking",
333→				slog.Int("message_index", i),
334→				slog.String("error", err.Error()),
335→			)
336→			continue
337→		}
338→		msgSize := len(msgBytes) + 1 // +1 for comma separator
339→
340→		if currentSize+msgSize > maxSize && len(currentMessages) > 0 {
341→			// Save current chunk
342→			chunkData, err := json.Marshal(GeminiTranscript{Messages: currentMessages})
343→			if err != nil {
344→				return nil, fmt.Errorf("failed to marshal chunk: %w", err)
345→			}
346→			chunks = append(chunks, chunkData)
347→
348→			// Start new chunk
349→			currentMessages = nil
350→			currentSize = len(`{"messages":[]}`)
351→		}
352→
353→		currentMessages = append(currentMessages, msg)
354→		currentSize += msgSize
355→	}
356→
357→	// Add the last chunk
358→	if len(currentMessages) > 0 {
359→		chunkData, err := json.Marshal(GeminiTranscript{Messages: currentMessages})
360→		if err != nil {
361→			return nil, fmt.Errorf("failed to marshal final chunk: %w", err)
362→		}
363→		chunks = append(chunks, chunkData)
364→	}
365→
366→	// Ensure we created at least one chunk (could be empty if all messages failed to marshal)
367→	if len(chunks) == 0 {
368→		return nil, errors.New("failed to create any chunks: all messages failed to marshal")
369→	}
370→
371→	return chunks, nil
372→}
373→
374→// ReassembleTranscript merges Gemini JSON chunks by combining their message arrays.
375→func (g *GeminiCLIAgent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
376→	var allMessages []GeminiMessage
377→
378→	for _, chunk := range chunks {
379→		var transcript GeminiTranscript
380→		if err := json.Unmarshal(chunk, &transcript); err != nil {
381→			return nil, fmt.Errorf("failed to unmarshal chunk: %w", err)
382→		}
383→		allMessages = append(allMessages, transcript.Messages...)
384→	}
385→
386→	result, err := json.Marshal(GeminiTranscript{Messages: allMessages})
387→	if err != nil {
388→		return nil, fmt.Errorf("failed to marshal reassembled transcript: %w", err)
389→	}
390→	return result, nil
391→}
