413→// resetShadowBranchToCheckpoint resets the shadow branch HEAD to the given checkpoint.
414→// This ensures that when the user commits after rewinding, the next checkpoint will only
415→// include prompts from the rewound point, not prompts from later checkpoints.
416→func (s *ManualCommitStrategy) resetShadowBranchToCheckpoint(ctx context.Context, repo *git.Repository, commit *object.Commit) error {
417→	// Extract session ID from the checkpoint commit's Entire-Session trailer
418→	sessionID, found := trailers.ParseSession(commit.Message)
419→	if !found {
420→		return errors.New("checkpoint has no Entire-Session trailer")
421→	}
422→
423→	// Load session state to get the shadow branch name
424→	state, err := s.loadSessionState(ctx, sessionID)
425→	if err != nil {
426→		return fmt.Errorf("failed to load session state: %w", err)
427→	}
428→	if state == nil {
429→		return fmt.Errorf("session %s not found", sessionID)
430→	}
431→
432→	// Reset the shadow branch to the checkpoint commit
433→	shadowBranchName := getShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
434→	refName := plumbing.NewBranchReferenceName(shadowBranchName)
435→
436→	// Update the reference to point to the checkpoint commit
437→	ref := plumbing.NewHashReference(refName, commit.Hash)
438→	if err := repo.Storer.SetReference(ref); err != nil {
439→		return fmt.Errorf("failed to update shadow branch: %w", err)
440→	}
441→
442→	fmt.Fprintf(os.Stderr, "[entire] Reset shadow branch %s to checkpoint %s\n", shadowBranchName, commit.Hash.String()[:7])
443→	return nil
444→}
