628→		fmt.Fprintf(os.Stderr, "Restoring %d sessions from checkpoint:\n", totalSessions)
629→	}
630→
631→	// Restore all sessions (oldest to newest, using 0-based indexing)
632→	var restored []RestoredSession
633→	for i := range totalSessions {
634→		content, readErr := store.ReadSessionContent(ctx, point.CheckpointID, i)
635→		if readErr != nil {
636→			fmt.Fprintf(os.Stderr, "  Warning: failed to read session %d: %v\n", i, readErr)
637→			continue
638→		}
639→		if content == nil || len(content.Transcript) == 0 {
640→			continue
641→		}
642→
643→		sessionID := content.Metadata.SessionID
644→		if sessionID == "" {
645→			fmt.Fprintf(os.Stderr, "  Warning: session %d has no session ID, skipping\n", i)
646→			continue
647→		}
648→
649→		// Resolve per-session agent from metadata — skip if agent is unknown
650→		if content.Metadata.Agent == "" {
651→			fmt.Fprintf(os.Stderr, "  Warning: session %d (%s) has no agent metadata, skipping (cannot determine target directory)\n", i, sessionID)
652→			continue
653→		}
654→		sessionAgent, agErr := ResolveAgentForRewind(content.Metadata.Agent)
655→		if agErr != nil {
656→			fmt.Fprintf(os.Stderr, "  Warning: session %d (%s) has unknown agent %q, skipping\n", i, sessionID, content.Metadata.Agent)
657→			continue
658→		}
659→
660→		// Compute transcript path from current repo location for cross-machine portability.
661→		sessionAgentDir, dirErr := sessionAgent.GetSessionDir(repoRoot)
662→		if dirErr != nil {
663→			fmt.Fprintf(os.Stderr, "  Warning: failed to get session dir for session %d: %v\n", i, dirErr)
664→			continue
665→		}
666→		sessionFile := sessionAgent.ResolveSessionFile(sessionAgentDir, sessionID)
667→
668→		// Get first prompt for display
669→		promptPreview := ExtractFirstPrompt(content.Prompts)
670→
671→		if totalSessions > 1 {
672→			isLatest := i == totalSessions-1
673→			if promptPreview != "" {
674→				if isLatest {
675→					fmt.Fprintf(os.Stderr, "  Session %d (latest): %s\n", i+1, promptPreview)
676→				} else {
677→					fmt.Fprintf(os.Stderr, "  Session %d: %s\n", i+1, promptPreview)
678→				}
679→			}
680→			fmt.Fprintf(os.Stderr, "    Writing to: %s\n", sessionFile)
681→		} else {
682→			fmt.Fprintf(os.Stderr, "Writing transcript to: %s\n", sessionFile)
683→		}
684→
685→		// Ensure parent directory exists (session file may be in a different dir than sessionAgentDir)
686→		if mkdirErr := os.MkdirAll(filepath.Dir(sessionFile), 0o750); mkdirErr != nil {
687→			fmt.Fprintf(os.Stderr, "    Warning: failed to create directory: %v\n", mkdirErr)
688→			continue
689→		}
690→
691→		agentSession := &agent.AgentSession{
692→			SessionID:  sessionID,
693→			AgentName:  sessionAgent.Name(),
694→			RepoPath:   repoRoot,
695→			SessionRef: sessionFile,
696→			NativeData: content.Transcript,
697→		}
698→		if writeErr := sessionAgent.WriteSession(ctx, agentSession); writeErr != nil {
699→			if totalSessions > 1 {
700→				fmt.Fprintf(os.Stderr, "    Warning: failed to write session: %v\n", writeErr)
701→				continue
702→			}
703→			return nil, fmt.Errorf("failed to write session: %w", writeErr)
704→		}
705→
706→		restored = append(restored, RestoredSession{
707→			SessionID: sessionID,
708→			Agent:     sessionAgent.Type(),
709→			Prompt:    promptPreview,
710→			CreatedAt: content.Metadata.CreatedAt,
711→		})
712→	}
713→
714→	return restored, nil
715→}
