717→// ResolveAgentForRewind resolves the agent from checkpoint metadata.
718→// Falls back to the default agent (Claude) for old checkpoints that lack agent info.
719→func ResolveAgentForRewind(agentType agent.AgentType) (agent.Agent, error) {
720→	if !isSpecificAgentType(agentType) {
721→		ag := agent.Default()
722→		if ag == nil {
723→			return nil, errors.New("no default agent registered")
724→		}
725→		return ag, nil
726→	}
727→	ag, err := agent.GetByAgentType(agentType)
728→	if err != nil {
729→		return nil, fmt.Errorf("resolving agent %q: %w", agentType, err)
730→	}
731→	return ag, nil
732→}
