734→// readSessionPrompt reads the first prompt from the session's prompt.txt file stored in git.
735→// Returns an empty string if the prompt cannot be read.
736→func readSessionPrompt(repo *git.Repository, commitHash plumbing.Hash, metadataDir string) string {
737→	// Get the commit and its tree
738→	commit, err := repo.CommitObject(commitHash)
739→	if err != nil {
740→		return ""
741→	}
742→
743→	tree, err := commit.Tree()
744→	if err != nil {
745→		return ""
746→	}
747→
748→	// Look for prompt.txt in the metadata directory
749→	promptPath := metadataDir + "/" + paths.PromptFileName
750→	promptEntry, err := tree.File(promptPath)
751→	if err != nil {
752→		return ""
753→	}
754→
755→	content, err := promptEntry.Contents()
756→	if err != nil {
757→		return ""
758→	}
759→
760→	return ExtractFirstPrompt(content)
761→}
