763→// SessionRestoreStatus represents the status of a session being restored.
764→type SessionRestoreStatus int
765→
766→const (
767→	StatusNew             SessionRestoreStatus = iota // Local file doesn't exist
768→	StatusUnchanged                                   // Local and checkpoint are the same
769→	StatusCheckpointNewer                             // Checkpoint has newer entries
770→	StatusLocalNewer                                  // Local has newer entries (conflict)
771→)
772→
773→// SessionRestoreInfo contains information about a session being restored.
774→type SessionRestoreInfo struct {
775→	SessionID      string
776→	Prompt         string               // First prompt preview for display
777→	Status         SessionRestoreStatus // Status of this session
778→	LocalTime      time.Time
779→	CheckpointTime time.Time
780→}
781→
782→// classifySessionsForRestore checks all sessions in a checkpoint and returns info
783→// about each session, including whether local logs have newer timestamps.
784→// repoRoot is used to compute per-session agent directories.
785→// Sessions without agent metadata are skipped (cannot determine target directory).
786→func (s *ManualCommitStrategy) classifySessionsForRestore(ctx context.Context, repoRoot string, store cpkg.Store, checkpointID id.CheckpointID, summary *cpkg.CheckpointSummary) []SessionRestoreInfo {
787→	var sessions []SessionRestoreInfo
788→
789→	totalSessions := len(summary.Sessions)
790→	// Check all sessions (0-based indexing)
791→	for i := range totalSessions {
792→		content, err := store.ReadSessionContent(ctx, checkpointID, i)
793→		if err != nil || content == nil || len(content.Transcript) == 0 {
794→			continue
795→		}
796→
797→		sessionID := content.Metadata.SessionID
798→		if sessionID == "" || content.Metadata.Agent == "" {
799→			continue
800→		}
801→
802→		sessionAgent, agErr := ResolveAgentForRewind(content.Metadata.Agent)
803→		if agErr != nil {
804→			continue
805→		}
806→
807→		// Compute transcript path from current repo location for cross-machine portability.
808→		sessionAgentDir, dirErr := sessionAgent.GetSessionDir(repoRoot)
809→		if dirErr != nil {
810→			continue
811→		}
812→		localPath := sessionAgent.ResolveSessionFile(sessionAgentDir, sessionID)
813→
814→		localTime := paths.GetLastTimestampFromFile(localPath)
815→		checkpointTime := paths.GetLastTimestampFromBytes(content.Transcript)
816→		status := ClassifyTimestamps(localTime, checkpointTime)
817→
818→		sessions = append(sessions, SessionRestoreInfo{
819→			SessionID:      sessionID,
820→			Prompt:         ExtractFirstPrompt(content.Prompts),
821→			Status:         status,
822→			LocalTime:      localTime,
823→			CheckpointTime: checkpointTime,
824→		})
825→	}
826→
827→	return sessions
828→}
829→
830→// ClassifyTimestamps determines the restore status based on local and checkpoint timestamps.
831→func ClassifyTimestamps(localTime, checkpointTime time.Time) SessionRestoreStatus {
832→	// Local file doesn't exist (no timestamp found)
833→	if localTime.IsZero() {
834→		return StatusNew
835→	}
836→
837→	// Can't determine checkpoint time - treat as new/safe
838→	if checkpointTime.IsZero() {
839→		return StatusNew
840→	}
841→
842→	// Compare timestamps
843→	if localTime.After(checkpointTime) {
844→		return StatusLocalNewer
845→	}
846→	if checkpointTime.After(localTime) {
847→		return StatusCheckpointNewer
848→	}
849→	return StatusUnchanged
850→}
851→
852→// StatusToText returns a human-readable status string.
853→func StatusToText(status SessionRestoreStatus) string {
854→	switch status {
855→	case StatusNew:
856→		return "(new)"
857→	case StatusUnchanged:
858→		return "(unchanged)"
859→	case StatusCheckpointNewer:
860→		return "(checkpoint is newer)"
861→	case StatusLocalNewer:
862→		return "(local is newer)" // shouldn't appear in non-conflict list
863→	default:
864→		return ""
865→	}
866→}
867→
868→// PromptOverwriteNewerLogs asks the user for confirmation to overwrite local
869→// session logs that have newer timestamps than the checkpoint versions.
870→func PromptOverwriteNewerLogs(sessions []SessionRestoreInfo) (bool, error) {
871→	// Separate conflicting and non-conflicting sessions
872→	var conflicting, nonConflicting []SessionRestoreInfo
873→	for _, s := range sessions {
874→		if s.Status == StatusLocalNewer {
875→			conflicting = append(conflicting, s)
876→		} else {
877→			nonConflicting = append(nonConflicting, s)
878→		}
879→	}
880→
881→	fmt.Fprintf(os.Stderr, "\nWarning: Local session log(s) have newer entries than the checkpoint:\n")
882→	for _, info := range conflicting {
883→		// Show prompt if available, otherwise fall back to session ID
884→		if info.Prompt != "" {
885→			fmt.Fprintf(os.Stderr, "  \"%s\"\n", info.Prompt)
886→		} else {
887→			fmt.Fprintf(os.Stderr, "  Session: %s\n", info.SessionID)
888→		}
889→		fmt.Fprintf(os.Stderr, "    Local last entry:      %s\n", info.LocalTime.Local().Format("2006-01-02 15:04:05"))
890→		fmt.Fprintf(os.Stderr, "    Checkpoint last entry: %s\n", info.CheckpointTime.Local().Format("2006-01-02 15:04:05"))
891→	}
892→
893→	// Show non-conflicting sessions with their status
894→	if len(nonConflicting) > 0 {
895→		fmt.Fprintf(os.Stderr, "\nThese other session(s) will also be restored:\n")
896→		for _, info := range nonConflicting {
897→			statusText := StatusToText(info.Status)
898→			if info.Prompt != "" {
899→				fmt.Fprintf(os.Stderr, "  \"%s\" %s\n", info.Prompt, statusText)
900→			} else {
901→				fmt.Fprintf(os.Stderr, "  Session: %s %s\n", info.SessionID, statusText)
902→			}
903→		}
904→	}
905→
906→	fmt.Fprintf(os.Stderr, "\nOverwriting will lose the newer local entries.\n\n")
907→
908→	var confirmed bool
909→	form := huh.NewForm(
910→		huh.NewGroup(
911→			huh.NewConfirm().
912→				Title("Overwrite local session logs with checkpoint versions?").
913→				Value(&confirmed),
914→		),
915→	)
916→	if isAccessibleMode() {
917→		form = form.WithAccessible(true)
918→	}
919→
920→	if err := form.Run(); err != nil {
921→		if errors.Is(err, huh.ErrUserAborted) {
922→			return false, nil
923→		}
924→		return false, fmt.Errorf("failed to get confirmation: %w", err)
925→	}
926→
927→	return confirmed, nil
928→}
