103→// GetAgentsWithHooksInstalled returns names of agents that have hooks installed.
104→func GetAgentsWithHooksInstalled(ctx context.Context) []agent.AgentName {
105→	var installed []agent.AgentName
106→	for _, name := range agent.List() {
107→		ag, err := agent.Get(name)
108→		if err != nil {
109→			continue
110→		}
111→		if hs, ok := ag.(agent.HookSupport); ok && hs.AreHooksInstalled(ctx) {
112→			installed = append(installed, name)
113→		}
114→	}
115→	return installed
