178→// classifySession determines if a session is stuck and returns diagnostic info.
179→// Returns nil if the session is healthy.
180→func classifySession(state *strategy.SessionState, repo *git.Repository, now time.Time) *stuckSession {
181→	// Determine shadow branch info
182→	shadowBranch := checkpoint.ShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
183→	refName := plumbing.NewBranchReferenceName(shadowBranch)
184→	_, refErr := repo.Reference(refName, true)
185→	hasShadowBranch := refErr == nil
186→
187→	switch {
188→	case state.Phase.IsActive():
189→		// Active sessions are stuck if no interaction for over the staleness threshold
190→		isStale := state.LastInteractionTime == nil || now.Sub(*state.LastInteractionTime) > stalenessThreshold
191→		if !isStale {
192→			return nil
193→		}
194→
195→		var reason string
196→		if state.LastInteractionTime != nil {
197→			reason = fmt.Sprintf("active, last interaction %s ago", now.Sub(*state.LastInteractionTime).Truncate(time.Minute))
198→		} else {
199→			reason = "active, no recorded interaction time"
200→		}
201→
202→		return &stuckSession{
203→			State:             state,
204→			Reason:            reason,
205→			ShadowBranch:      shadowBranch,
206→			HasShadowBranch:   hasShadowBranch,
207→			CheckpointCount:   state.StepCount,
208→			FilesTouchedCount: len(state.FilesTouched),
209→		}
210→
211→	case state.Phase == session.PhaseEnded:
212→		// Ended sessions are stuck if they have uncondensed data
213→		if state.StepCount <= 0 || !hasShadowBranch {
214→			return nil
215→		}
216→
217→		return &stuckSession{
218→			State:             state,
219→			Reason:            "ended with uncondensed checkpoint data",
220→			ShadowBranch:      shadowBranch,
221→			HasShadowBranch:   hasShadowBranch,
222→			CheckpointCount:   state.StepCount,
223→			FilesTouchedCount: len(state.FilesTouched),
224→		}
225→
226→	default:
227→		return nil
228→	}
229→}
