255→// promptSessionAction asks the user what to do with a stuck session.
256→func promptSessionAction(ss stuckSession) (string, error) {
257→	var action string
258→
259→	options := make([]huh.Option[string], 0, 3)
260→	if ss.HasShadowBranch && ss.CheckpointCount > 0 {
261→		options = append(options, huh.NewOption("Condense (save to permanent storage)", "condense"))
262→	}
263→	options = append(options,
264→		huh.NewOption("Discard (remove session data)", "discard"),
265→		huh.NewOption("Skip (leave as-is)", "skip"),
266→	)
267→
268→	form := NewAccessibleForm(
269→		huh.NewGroup(
270→			huh.NewSelect[string]().
271→				Title(fmt.Sprintf("Fix session %s?", ss.State.SessionID)).
272→				Options(options...).
273→				Value(&action),
274→		),
275→	)
276→
277→	if err := form.Run(); err != nil {
278→		return "", fmt.Errorf("session fix prompt failed: %w", err)
279→	}
280→
281→	return action, nil
282→}
