284→// discardSession removes session state and cleans up the shadow branch.
285→func discardSession(ctx context.Context, ss stuckSession, _ *git.Repository, errW io.Writer) error {
286→	// Clear session state file
287→	if err := strategy.ClearSessionState(ctx, ss.State.SessionID); err != nil {
288→		return fmt.Errorf("failed to clear session state: %w", err)
289→	}
290→
291→	// Delete shadow branch if it exists and no other sessions need it
292→	if ss.HasShadowBranch {
293→		if shouldDelete, err := canDeleteShadowBranch(ctx, ss.ShadowBranch, ss.State.SessionID); err != nil {
294→			fmt.Fprintf(errW, "Warning: could not check other sessions for shadow branch: %v\n", err)
295→		} else if shouldDelete {
296→			if err := strategy.DeleteBranchCLI(ctx, ss.ShadowBranch); err != nil {
297→				// Branch already gone is not an error — keeps discard idempotent
298→				if !errors.Is(err, strategy.ErrBranchNotFound) {
299→					return fmt.Errorf("failed to delete shadow branch: %w", err)
300→				}
301→			}
302→		}
303→	}
304→
305→	return nil
306→}
307→
308→// canDeleteShadowBranch checks if a shadow branch can be safely deleted.
309→// Returns true if no other sessions (besides excludeSessionID) need this branch.
310→func canDeleteShadowBranch(ctx context.Context, shadowBranch, excludeSessionID string) (bool, error) {
311→	states, err := strategy.ListSessionStates(ctx)
312→	if err != nil {
313→		return false, fmt.Errorf("failed to list session states: %w", err)
314→	}
315→
316→	for _, state := range states {
317→		if state.SessionID == excludeSessionID {
318→			continue
319→		}
320→		otherShadow := checkpoint.ShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
321→		if otherShadow == shadowBranch && state.StepCount > 0 {
322→			return false, nil
323→		}
324→	}
325→
326→	return true, nil
327→}
