161→// TransitionAndLog runs a session phase transition, applies actions via the
162→// handler, and logs the transition. Returns the first handler error from
163→// ApplyTransition (if any) so callers can surface it. The error is also
164→// logged internally for diagnostics.
165→// This is the single entry point for all state machine transitions to ensure
166→// consistent logging of phase changes.
167→func TransitionAndLog(goCtx context.Context, state *SessionState, event session.Event, ctx session.TransitionContext, handler session.ActionHandler) error {
168→	oldPhase := state.Phase
169→	result := session.Transition(oldPhase, event, ctx)
170→	logCtx := logging.WithComponent(goCtx, "session")
171→
172→	handlerErr := session.ApplyTransition(goCtx, state, result, handler)
173→	if handlerErr != nil {
174→		logging.Error(logCtx, "action handler error during transition",
175→			slog.String("session_id", state.SessionID),
176→			slog.String("event", event.String()),
177→			slog.Any("error", handlerErr),
178→		)
179→	}
180→
181→	if result.NewPhase != oldPhase {
182→		logging.Info(logCtx, "phase transition",
183→			slog.String("session_id", state.SessionID),
184→			slog.String("event", event.String()),
185→			slog.String("from", string(oldPhase)),
186→			slog.String("to", string(result.NewPhase)),
187→		)
188→	} else {
189→		logging.Debug(logCtx, "phase unchanged",
190→			slog.String("session_id", state.SessionID),
191→			slog.String("event", event.String()),
192→			slog.String("phase", string(result.NewPhase)),
193→			slog.Any("result", result),
194→		)
195→	}
196→
197→	if handlerErr != nil {
198→		return fmt.Errorf("transition %s: %w", event, handlerErr)
199→	}
200→	return nil
201→}
202→
203→// ClearSessionState removes the session state file for the given session ID.
204→func ClearSessionState(ctx context.Context, sessionID string) error {
205→	// Validate session ID to prevent path traversal
206→	if err := validation.ValidateSessionID(sessionID); err != nil {
207→		return fmt.Errorf("invalid session ID: %w", err)
208→	}
209→
210→	stateFile, err := sessionStateFile(ctx, sessionID)
211→	if err != nil {
212→		return fmt.Errorf("failed to get session state file path: %w", err)
213→	}
214→
215→	if err := os.Remove(stateFile); err != nil {
216→		if os.IsNotExist(err) {
217→			return nil // Already gone, not an error
218→		}
219→		return fmt.Errorf("failed to remove session state file: %w", err)
220→	}
221→	return nil
222→}
