 14→// hookManager describes an external hook manager detected in a repository.
 15→type hookManager struct {
 16→	Name            string // "Husky", "Lefthook", "pre-commit", "Overcommit"
 17→	ConfigPath      string // relative path that triggered detection (e.g., ".husky/")
 18→	OverwritesHooks bool   // true if the tool will overwrite Entire's hooks on reinstall
 19→}
 20→
 21→// detectHookManagers checks the repository root for known hook manager config
 22→// files/directories. Detection is filesystem-only (os.Stat, no file reads).
 23→func detectHookManagers(repoRoot string) []hookManager {
 24→	var managers []hookManager
 25→
 26→	checks := []hookManager{
 27→		{"Husky", ".husky/", true},
 28→		{"pre-commit", ".pre-commit-config.yaml", false},
 29→		{"Overcommit", ".overcommit.yml", false},
 30→	}
 31→
 32→	// Lefthook supports {.,}lefthook{,-local}.{yml,yaml,json,toml}
 33→	for _, prefix := range []string{"", "."} {
 34→		for _, variant := range []string{"", "-local"} {
 35→			for _, ext := range []string{"yml", "yaml", "json", "toml"} {
 36→				name := prefix + "lefthook" + variant + "." + ext
 37→				checks = append(checks, hookManager{"Lefthook", name, false})
 38→			}
 39→		}
 40→	}
 41→
 42→	seen := make(map[string]bool)
 43→	for _, c := range checks {
 44→		path := filepath.Join(repoRoot, c.ConfigPath)
 45→		if _, err := os.Stat(path); err == nil {
 46→			if seen[c.Name] {
 47→				continue // e.g., lefthook.yml and .lefthook.yml both present
 48→			}
 49→			seen[c.Name] = true
 50→			managers = append(managers, c)
 51→		}
 52→	}
 53→
 54→	return managers
 55→}
 56→
 57→// hookManagerWarning builds a warning string for detected hook managers.
 58→// cmdPrefix is the CLI command prefix (e.g., "entire" or "go run ./cmd/entire/main.go").
 59→func hookManagerWarning(managers []hookManager, cmdPrefix string) string {
 60→	if len(managers) == 0 {
 61→		return ""
 62→	}
 63→
 64→	var b strings.Builder
 65→
 66→	specs := buildHookSpecs(cmdPrefix)
 67→
 68→	for _, m := range managers {
 69→		if m.OverwritesHooks {
 70→			fmt.Fprintf(&b, "Warning: %s detected (%s)\n", m.Name, m.ConfigPath)
 71→			fmt.Fprintf(&b, "\n")
 72→			fmt.Fprintf(&b, "  %s may overwrite hooks installed by Entire on npm install.\n", m.Name)
 73→			fmt.Fprintf(&b, "  To make Entire hooks permanent, add these lines to your %s hook files:\n", m.Name)
 74→			fmt.Fprintf(&b, "\n")
 75→
 76→			// Use the config path as the hook directory prefix for hook files.
 77→			// For Husky, this is typically ".husky/" where hook scripts are stored.
 78→			hookDir := m.ConfigPath
 79→
 80→			for _, spec := range specs {
 81→				cmdLine := extractCommandLine(spec.content)
 82→				if cmdLine == "" {
 83→					continue
 84→				}
 85→				fmt.Fprintf(&b, "    %s%s:\n", hookDir, spec.name)
 86→				fmt.Fprintf(&b, "      %s\n", cmdLine)
 87→				fmt.Fprintf(&b, "\n")
 88→			}
 89→		} else {
 90→			fmt.Fprintf(&b, "Note: %s detected (%s)\n", m.Name, m.ConfigPath)
 91→			fmt.Fprintf(&b, "\n")
 92→			fmt.Fprintf(&b, "  If %s reinstalls hooks, run 'entire enable' to restore Entire's hooks.\n", m.Name)
 93→			fmt.Fprintf(&b, "\n")
 94→		}
 95→	}
 96→
 97→	return b.String()
 98→}
