416→		result.FailedBranches = failed
417→
418→		// Log deleted branches
419→		for _, id := range deleted {
420→			logging.Info(logCtx, "deleted orphaned shadow branch",
421→				slog.String("type", string(CleanupTypeShadowBranch)),
422→				slog.String("id", id),
423→				slog.String("reason", reasonMap[id]),
424→			)
425→		}
426→		// Log failed branches
427→		for _, id := range failed {
428→			logging.Warn(logCtx, "failed to delete orphaned shadow branch",
429→				slog.String("type", string(CleanupTypeShadowBranch)),
430→				slog.String("id", id),
431→				slog.String("reason", reasonMap[id]),
432→			)
433→		}
434→	}
435→
436→	// Delete session states
437→	if len(states) > 0 {
438→		deleted, failed, err := DeleteOrphanedSessionStates(ctx, states)
439→		if err != nil {
440→			return result, err
441→		}
442→		result.SessionStates = deleted
443→		result.FailedStates = failed
444→
445→		// Log deleted session states
446→		for _, id := range deleted {
447→			logging.Info(logCtx, "deleted orphaned session state",
448→				slog.String("type", string(CleanupTypeSessionState)),
449→				slog.String("id", id),
450→				slog.String("reason", reasonMap[id]),
451→			)
452→		}
453→		// Log failed session states
454→		for _, id := range failed {
455→			logging.Warn(logCtx, "failed to delete orphaned session state",
456→				slog.String("type", string(CleanupTypeSessionState)),
457→				slog.String("id", id),
458→				slog.String("reason", reasonMap[id]),
459→			)
460→		}
461→	}
462→
463→	// Delete checkpoints
464→	if len(checkpoints) > 0 {
465→		deleted, failed, err := DeleteOrphanedCheckpoints(ctx, checkpoints)
466→		if err != nil {
467→			return result, err
468→		}
469→		result.Checkpoints = deleted
470→		result.FailedCheckpoints = failed
471→
472→		// Log deleted checkpoints
473→		for _, id := range deleted {
474→			logging.Info(logCtx, "deleted orphaned checkpoint",
475→				slog.String("type", string(CleanupTypeCheckpoint)),
476→				slog.String("id", id),
477→				slog.String("reason", reasonMap[id]),
478→			)
479→		}
480→		// Log failed checkpoints
481→		for _, id := range failed {
482→			logging.Warn(logCtx, "failed to delete orphaned checkpoint",
483→				slog.String("type", string(CleanupTypeCheckpoint)),
484→				slog.String("id", id),
485→				slog.String("reason", reasonMap[id]),
486→			)
487→		}
488→	}
489→
490→	// Log summary
491→	totalDeleted := len(result.ShadowBranches) + len(result.SessionStates) + len(result.Checkpoints)
492→	totalFailed := len(result.FailedBranches) + len(result.FailedStates) + len(result.FailedCheckpoints)
493→	if totalDeleted > 0 || totalFailed > 0 {
494→		logging.Info(logCtx, "cleanup completed",
495→			slog.Int("deleted_branches", len(result.ShadowBranches)),
496→			slog.Int("deleted_session_states", len(result.SessionStates)),
497→			slog.Int("deleted_checkpoints", len(result.Checkpoints)),
498→			slog.Int("failed_branches", len(result.FailedBranches)),
499→			slog.Int("failed_session_states", len(result.FailedStates)),
500→			slog.Int("failed_checkpoints", len(result.FailedCheckpoints)),
501→		)
502→	}
503→
504→	return result, nil
505→}
