 73→// ChunkTranscript splits an OpenCode export JSON transcript by distributing messages across chunks.
 74→// OpenCode uses JSON format with {"info": {...}, "messages": [...]} structure.
 75→func (a *OpenCodeAgent) ChunkTranscript(_ context.Context, content []byte, maxSize int) ([][]byte, error) {
 76→	var session ExportSession
 77→	if err := json.Unmarshal(content, &session); err != nil {
 78→		return nil, fmt.Errorf("failed to parse export session for chunking: %w", err)
 79→	}
 80→
 81→	if len(session.Messages) == 0 {
 82→		return [][]byte{content}, nil
 83→	}
 84→
 85→	// Marshal info to calculate accurate base size
 86→	infoBytes, err := json.Marshal(session.Info)
 87→	if err != nil {
 88→		return nil, fmt.Errorf("failed to marshal session info for chunking: %w", err)
 89→	}
 90→	// Base JSON structure size: {"info":<info>,"messages":[ ... ]}
 91→	baseSize := len(`{"info":`) + len(infoBytes) + len(`,"messages":[]}`)
 92→
 93→	var chunks [][]byte
 94→	var currentMessages []ExportMessage
 95→	currentSize := baseSize
 96→
 97→	for _, msg := range session.Messages {
 98→		// Marshal message to get its size
 99→		msgBytes, err := json.Marshal(msg)
100→		if err != nil {
101→			return nil, fmt.Errorf("failed to marshal message for chunking: %w", err)
102→		}
103→		msgSize := len(msgBytes) + 1 // +1 for comma separator
104→
105→		if currentSize+msgSize > maxSize && len(currentMessages) > 0 {
106→			// Save current chunk
107→			chunkData, err := json.Marshal(ExportSession{Info: session.Info, Messages: currentMessages})
108→			if err != nil {
109→				return nil, fmt.Errorf("failed to marshal chunk: %w", err)
110→			}
111→			chunks = append(chunks, chunkData)
112→
113→			// Start new chunk
114→			currentMessages = nil
115→			currentSize = baseSize
116→		}
117→
118→		currentMessages = append(currentMessages, msg)
119→		currentSize += msgSize
120→	}
121→
122→	// Add the last chunk
123→	if len(currentMessages) > 0 {
124→		chunkData, err := json.Marshal(ExportSession{Info: session.Info, Messages: currentMessages})
125→		if err != nil {
126→			return nil, fmt.Errorf("failed to marshal final chunk: %w", err)
127→		}
128→		chunks = append(chunks, chunkData)
129→	}
130→
131→	if len(chunks) == 0 {
132→		return nil, errors.New("failed to create any chunks")
133→	}
134→
135→	return chunks, nil
136→}
137→
138→// ReassembleTranscript merges OpenCode export JSON chunks by combining their message arrays.
139→func (a *OpenCodeAgent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
140→	if len(chunks) == 0 {
141→		return nil, errors.New("no chunks to reassemble")
142→	}
143→
144→	var allMessages []ExportMessage
145→	var sessionInfo SessionInfo
146→
147→	for i, chunk := range chunks {
148→		var session ExportSession
149→		if err := json.Unmarshal(chunk, &session); err != nil {
150→			return nil, fmt.Errorf("failed to unmarshal chunk %d: %w", i, err)
151→		}
152→		if i == 0 {
153→			sessionInfo = session.Info // Preserve session info from first chunk
154→		}
155→		allMessages = append(allMessages, session.Messages...)
156→	}
157→
158→	result, err := json.Marshal(ExportSession{Info: sessionInfo, Messages: allMessages})
159→	if err != nil {
160→		return nil, fmt.Errorf("failed to marshal reassembled transcript: %w", err)
161→	}
162→	return result, nil
163→}
