171→// GetSessionDir returns the directory where Entire stores OpenCode session transcripts.
172→// Transcripts are ephemeral handoff files between the TS plugin and the Go hook handler.
173→// Once checkpointed, the data lives on git refs and the file is disposable.
174→// Stored in os.TempDir()/entire-opencode/<sanitized-path>/ to avoid squatting on
175→// OpenCode's own directories (~/.opencode/ is project-level, not home-level).
176→func (a *OpenCodeAgent) GetSessionDir(repoPath string) (string, error) {
177→	// Check for test environment override
178→	if override := os.Getenv("ENTIRE_TEST_OPENCODE_PROJECT_DIR"); override != "" {
179→		return override, nil
180→	}
181→
182→	projectDir := SanitizePathForOpenCode(repoPath)
183→	return filepath.Join(os.TempDir(), "entire-opencode", projectDir), nil
184→}
