190→func (a *OpenCodeAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
191→	if input.SessionRef == "" {
192→		return nil, errors.New("no session ref provided")
193→	}
194→	data, err := os.ReadFile(input.SessionRef)
195→	if err != nil {
196→		return nil, fmt.Errorf("failed to read session: %w", err)
197→	}
198→
199→	// Parse to extract computed fields
200→	modifiedFiles, err := ExtractModifiedFiles(data)
201→	if err != nil {
202→		// Non-fatal: we can still return the session without modified files
203→		logging.Warn(context.Background(), "failed to extract modified files from opencode session",
204→			slog.String("session_ref", input.SessionRef),
205→			slog.String("error", err.Error()),
206→		)
207→		modifiedFiles = nil
208→	}
209→
210→	return &agent.AgentSession{
211→		AgentName:     a.Name(),
212→		SessionID:     input.SessionID,
213→		SessionRef:    input.SessionRef,
214→		NativeData:    data,
215→		ModifiedFiles: modifiedFiles,
216→	}, nil
217→}
