219→func (a *OpenCodeAgent) WriteSession(ctx context.Context, session *agent.AgentSession) error {
220→	if session == nil {
221→		return errors.New("nil session")
222→	}
223→	if len(session.NativeData) == 0 {
224→		return errors.New("no session data to write")
225→	}
226→
227→	// Import the session into OpenCode's database.
228→	// This enables `opencode -s <id>` for both resume and rewind.
229→	return a.importSessionIntoOpenCode(ctx, session.SessionID, session.NativeData)
230→}
231→
232→// importSessionIntoOpenCode writes the export JSON to a temp file and runs
233→// `opencode import` to restore the session into OpenCode's database.
234→// For rewind (session already exists), the session is deleted first so the
235→// reimport replaces it with the checkpoint-state messages.
236→func (a *OpenCodeAgent) importSessionIntoOpenCode(ctx context.Context, sessionID string, exportData []byte) error {
237→	// Delete existing session first so reimport replaces it cleanly.
238→	// opencode import uses ON CONFLICT DO NOTHING, so existing messages
239→	// would be skipped without this step (breaking rewind).
240→	if err := runOpenCodeSessionDelete(ctx, sessionID); err != nil {
241→		// Non-fatal: session might not exist yet (first session).
242→		// Import will still work for new sessions; only rewind of existing sessions
243→		// would have stale messages.
244→		logging.Warn(ctx, "could not delete existing opencode session",
245→			slog.String("session_id", sessionID),
246→			slog.String("error", err.Error()),
247→		)
248→	}
249→
250→	// Write export JSON to a temp file for opencode import
251→	tmpFile, err := os.CreateTemp("", "entire-opencode-export-*.json")
252→	if err != nil {
253→		return fmt.Errorf("failed to create temp file: %w", err)
254→	}
255→	defer os.Remove(tmpFile.Name())
256→
257→	if _, err := tmpFile.Write(exportData); err != nil {
258→		_ = tmpFile.Close()
259→		return fmt.Errorf("failed to write export data: %w", err)
260→	}
261→	if err := tmpFile.Close(); err != nil {
262→		return fmt.Errorf("failed to close temp file: %w", err)
263→	}
264→
265→	return runOpenCodeImport(ctx, tmpFile.Name())
266→}
267→
268→func (a *OpenCodeAgent) FormatResumeCommand(sessionID string) string {
269→	if strings.TrimSpace(sessionID) == "" {
270→		return "opencode"
271→	}
272→	return "opencode -s " + sessionID
273→}
274→
275→// nonAlphanumericRegex matches any non-alphanumeric character.
276→var nonAlphanumericRegex = regexp.MustCompile(`[^a-zA-Z0-9]`)
277→
278→// SanitizePathForOpenCode converts a path to a safe directory name.
279→// Replaces any non-alphanumeric character with a dash (same approach as Claude/Gemini).
280→func SanitizePathForOpenCode(path string) string {
281→	return nonAlphanumericRegex.ReplaceAllString(path, "-")
282→}
