func newStatusCmd() *cobra.Command {
	var detailed bool

	cmd := &cobra.Command{
		Use:   "status",
		Short: "Show Entire status",
		Long:  "Show whether Entire is currently enabled or disabled",
		RunE: func(cmd *cobra.Command, _ []string) error {
			return runStatus(cmd.OutOrStdout(), detailed)
		},
	}

	cmd.Flags().BoolVar(&detailed, "detailed", false, "Show detailed status for each settings file")

	return cmd
}

func runStatus(w io.Writer, detailed bool) error {
	// Check if we're in a git repository
	if _, repoErr := paths.WorktreeRoot(); repoErr != nil {
		fmt.Fprintln(w, "✕ not a git repository")
		return nil //nolint:nilerr // Not being in a git repo is a valid status, not an error
	}

	// Get absolute paths for settings files
	settingsPath, err := paths.AbsPath(EntireSettingsFile)
	if err != nil {
		settingsPath = EntireSettingsFile
	}
	localSettingsPath, err := paths.AbsPath(EntireSettingsLocalFile)
	if err != nil {
		localSettingsPath = EntireSettingsLocalFile
	}

	// Check which settings files exist
	_, projectErr := os.Stat(settingsPath)
	if projectErr != nil && !errors.Is(projectErr, fs.ErrNotExist) {
		return fmt.Errorf("cannot access project settings file: %w", projectErr)
	}
	_, localErr := os.Stat(localSettingsPath)
	if localErr != nil && !errors.Is(localErr, fs.ErrNotExist) {
		return fmt.Errorf("cannot access local settings file: %w", localErr)
	}
	projectExists := projectErr == nil
	localExists := localErr == nil

	if !projectExists && !localExists {
		fmt.Fprintln(w, "○ not set up (run `entire enable` to get started)")
		return nil
	}

	sty := newStatusStyles(w)

	if detailed {
		return runStatusDetailed(w, sty, settingsPath, localSettingsPath, projectExists, localExists)
	}

	// Short output: just show the effective/merged state
	s, err := LoadEntireSettings()
	if err != nil {
		return fmt.Errorf("failed to load settings: %w", err)
	}

	fmt.Fprintln(w)
	settings.WriteDeprecatedStrategyWarnings(w)
	fmt.Fprintln(w)
	fmt.Fprintln(w, formatSettingsStatusShort(s, sty))
	if s.Enabled {
		writeActiveSessions(w, sty)
	}

	return nil
}

// runStatusDetailed shows the effective status plus detailed status for each settings file.
func runStatusDetailed(w io.Writer, sty statusStyles, settingsPath, localSettingsPath string, projectExists, localExists bool) error {
	// First show the effective/merged status
	effectiveSettings, err := LoadEntireSettings()
	if err != nil {
		return fmt.Errorf("failed to load settings: %w", err)
	}
	fmt.Fprintln(w)
	settings.WriteDeprecatedStrategyWarnings(w)
	fmt.Fprintln(w)
	fmt.Fprintln(w, formatSettingsStatusShort(effectiveSettings, sty))
	fmt.Fprintln(w) // blank line

	// Show project settings if it exists
	if projectExists {
		projectSettings, err := settings.LoadFromFile(settingsPath)
		if err != nil {
			return fmt.Errorf("failed to load project settings: %w", err)
		}
		fmt.Fprintln(w, formatSettingsStatus("Project", projectSettings, sty))
	}

	// Show local settings if it exists
	if localExists {
		localSettings, err := settings.LoadFromFile(localSettingsPath)
		if err != nil {
			return fmt.Errorf("failed to load local settings: %w", err)
		}
		fmt.Fprintln(w, formatSettingsStatus("Local", localSettings, sty))
	}

	if effectiveSettings.Enabled {
		writeActiveSessions(w, sty)
	}

	return nil
}

// formatSettingsStatusShort formats a short settings status line.
// Output format: "● Enabled · manual-commit · branch main" or "○ Disabled"
func formatSettingsStatusShort(s *EntireSettings, sty statusStyles) string {
	displayName := strategy.StrategyNameManualCommit

	var b strings.Builder

	if s.Enabled {
		b.WriteString(sty.render(sty.green, "●"))
		b.WriteString(" ")
		b.WriteString(sty.render(sty.bold, "Enabled"))
	} else {
		b.WriteString(sty.render(sty.red, "○"))
		b.WriteString(" ")
		b.WriteString(sty.render(sty.bold, "Disabled"))
	}

	b.WriteString(sty.render(sty.dim, " · "))
	b.WriteString(displayName)

	// Resolve branch from repo root
	if repoRoot, err := paths.WorktreeRoot(); err == nil {
		if branch := resolveWorktreeBranch(repoRoot); branch != "" {
			b.WriteString(sty.render(sty.dim, " · "))
			b.WriteString("branch ")
			b.WriteString(sty.render(sty.cyan, branch))
		}
	}

	return b.String()
}

// formatSettingsStatus formats a settings status line with source prefix.
// Output format: "Project · enabled · manual-commit" or "Local · disabled"
func formatSettingsStatus(prefix string, s *EntireSettings, sty statusStyles) string {
	displayName := strategy.StrategyNameManualCommit

	var b strings.Builder
	b.WriteString(sty.render(sty.bold, prefix))
	b.WriteString(sty.render(sty.dim, " · "))

	if s.Enabled {
		b.WriteString("enabled")
	} else {
		b.WriteString("disabled")
	}

	b.WriteString(sty.render(sty.dim, " · "))
	b.WriteString(displayName)

	return b.String()
}

// timeAgo formats a time as a human-readable relative duration.
func timeAgo(t time.Time) string {
	d := time.Since(t)
	switch {
	case d < time.Minute:
		return "just now"
	case d < time.Hour:
		m := int(d.Minutes())
		return fmt.Sprintf("%dm ago", m)
	case d < 24*time.Hour:
		h := int(d.Hours())
		return fmt.Sprintf("%dh ago", h)
	default:
		days := int(d.Hours() / 24)
		return fmt.Sprintf("%dd ago", days)
	}
}

// worktreeGroup groups sessions by worktree path for display.
type worktreeGroup struct {
	path     string
	branch   string
	sessions []*session.State
}

const (
	unknownPlaceholder  = "(unknown)"
	detachedHEADDisplay = "HEAD"
)

// writeActiveSessions writes active session information grouped by worktree.
func writeActiveSessions(w io.Writer, sty statusStyles) {
	store, err := session.NewStateStore()
	if err != nil {
		return
	}

	states, err := store.List(context.Background())
	if err != nil || len(states) == 0 {
		return
	}

	// Filter to active sessions only
	var active []*session.State
	for _, s := range states {
		if s.EndedAt == nil {
			active = append(active, s)
		}
	}
	if len(active) == 0 {
		return
	}

	// Group by worktree path
	groups := make(map[string]*worktreeGroup)
	for _, s := range active {
		wp := s.WorktreePath
		if wp == "" {
			wp = unknownPlaceholder
		}
		g, ok := groups[wp]
		if !ok {
			g = &worktreeGroup{path: wp}
			groups[wp] = g
		}
		g.sessions = append(g.sessions, s)
	}

	// Resolve branch names for each worktree (skip for unknown paths)
	for _, g := range groups {
		if g.path != unknownPlaceholder {
			g.branch = resolveWorktreeBranch(g.path)
		}
	}

	// Sort groups: alphabetical by path
	sortedGroups := make([]*worktreeGroup, 0, len(groups))
	for _, g := range groups {
		sortedGroups = append(sortedGroups, g)
	}
	sort.Slice(sortedGroups, func(i, j int) bool {
		return sortedGroups[i].path < sortedGroups[j].path
	})

	// Sort sessions within each group by StartedAt (newest first)
	for _, g := range sortedGroups {
		sort.Slice(g.sessions, func(i, j int) bool {
			return g.sessions[i].StartedAt.After(g.sessions[j].StartedAt)
		})
	}

	// Track aggregate totals
	var totalSessions int

	fmt.Fprintln(w)
	printedHeader := false
	for _, g := range sortedGroups {
		if !printedHeader {
			fmt.Fprintln(w, sty.sectionRule("Active Sessions", sty.width))
			fmt.Fprintln(w)
			printedHeader = true
		}

		for _, st := range g.sessions {
			totalSessions++

			agentLabel := string(st.AgentType)
			if agentLabel == "" {
				agentLabel = unknownPlaceholder
			}

			shortID := st.SessionID
			if len(shortID) > 7 {
				shortID = shortID[:7]
			}

			// Line 1: Agent · shortID
			fmt.Fprintf(w, "%s %s %s\n",
				sty.render(sty.agent, agentLabel),
				sty.render(sty.dim, "·"),
				shortID)

			// Line 2: > "first prompt" (chevron + quoted, truncated)
			if st.FirstPrompt != "" {
				prompt := stringutil.TruncateRunes(st.FirstPrompt, 60, "...")
				fmt.Fprintf(w, "%s \"%s\"\n", sty.render(sty.dim, ">"), prompt)
			}

			// Line 3: stats line — started Xd ago · active now · files N · tokens X.Xk
			var stats []string
			stats = append(stats, "started "+timeAgo(st.StartedAt))

			if st.LastInteractionTime != nil && st.LastInteractionTime.Sub(st.StartedAt) > time.Minute {
				stats = append(stats, activeTimeDisplay(st.LastInteractionTime))
			}

			stats = append(stats, "tokens "+formatTokenCount(totalTokens(st.TokenUsage)))

			statsLine := strings.Join(stats, sty.render(sty.dim, " · "))
			fmt.Fprintln(w, sty.render(sty.dim, statsLine))
			fmt.Fprintln(w)
		}
	}

	// Footer: horizontal rule + session count
	fmt.Fprintln(w, sty.horizontalRule(sty.width))
	var footer string
	if totalSessions == 1 {
		footer = "1 session"
	} else {
		footer = fmt.Sprintf("%d sessions", totalSessions)
	}
	fmt.Fprintln(w, sty.render(sty.dim, footer))
	fmt.Fprintln(w)
}

// resolveWorktreeBranch resolves the current branch for a worktree path
// by reading the HEAD ref directly from the filesystem
func resolveWorktreeBranch(worktreePath string) string {
	gitPath := filepath.Join(worktreePath, ".git")

	fi, err := os.Stat(gitPath)
	if err != nil {
		return ""
	}

	var headPath string
	if fi.IsDir() {
		// Regular repo: .git is a directory
		headPath = filepath.Join(gitPath, "HEAD")
	} else {
		// Worktree: .git is a file containing "gitdir: <path>"
		data, err := os.ReadFile(gitPath) //nolint:gosec // path derived from known worktree dir
		if err != nil {
			return ""
		}
		content := strings.TrimSpace(string(data))
		if !strings.HasPrefix(content, "gitdir: ") {
			return ""
		}
		gitdirPath := strings.TrimPrefix(content, "gitdir: ")
		if !filepath.IsAbs(gitdirPath) {
			gitdirPath = filepath.Join(worktreePath, gitdirPath)
		}
		headPath = filepath.Join(gitdirPath, "HEAD")
	}

	data, err := os.ReadFile(headPath) //nolint:gosec // path constructed from .git/HEAD
	if err != nil {
		return ""
	}

	ref := strings.TrimSpace(string(data))

	// Symbolic ref: "ref: refs/heads/<branch>"
	if strings.HasPrefix(ref, "ref: refs/heads/") {
		branch := strings.TrimPrefix(ref, "ref: refs/heads/")
		// Reftable ref storage uses "ref: refs/heads/.invalid" as a dummy HEAD stub.
		// Fall back to git to resolve the actual branch in that case.
		if branch == ".invalid" {
			return resolveWorktreeBranchGit(worktreePath)
		}
		return branch
	}

	// Detached HEAD or other ref type
	return detachedHEADDisplay
}

// resolveWorktreeBranchGit resolves the branch name by shelling out to git.
// Used as a fallback for reftable ref storage where .git/HEAD is a stub.
func resolveWorktreeBranchGit(worktreePath string) string {
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	cmd := exec.CommandContext(ctx, "git", "-C", worktreePath, "rev-parse", "--symbolic-full-name", "HEAD")
	out, err := cmd.Output()
	if err != nil {
		return detachedHEADDisplay
	}
	ref := strings.TrimSpace(string(out))
	if strings.HasPrefix(ref, "refs/heads/") {
		return strings.TrimPrefix(ref, "refs/heads/")
	}
	return detachedHEADDisplay
}

package cli

import (
	"bufio"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"

	agentpkg "github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/claudecode"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/textutil"
	"github.com/entireio/cli/cmd/entire/cli/transcript"
)

// Transcript message type constants - aliases to transcript package for local use.
const (
	transcriptTypeUser      = transcript.TypeUser
	transcriptTypeAssistant = transcript.TypeAssistant
	contentTypeText         = transcript.ContentTypeText
	contentTypeToolUse      = transcript.ContentTypeToolUse
)

// PromptResponsePair represents a user prompt and the assistant's responses.
// Used for extracting all interactions from a transcript.
type PromptResponsePair struct {
	Prompt    string
	Responses []string // Multiple responses can occur between tool calls
	Files     []string
}

// ExtractAllPromptResponses extracts all user prompt and assistant response pairs from a transcript.
// Returns pairs in chronological order (oldest first).
// Each pair contains the user's prompt, assistant's text response, and files modified.
func ExtractAllPromptResponses(transcript []transcriptLine) []PromptResponsePair {
	var pairs []PromptResponsePair

	// Find all user prompts (messages with string content, not tool results)
	var userIndices []int
	for i, line := range transcript {
		if line.Type == transcriptTypeUser {
			var msg userMessage
			if err := json.Unmarshal(line.Message, &msg); err != nil {
				continue
			}
			// Only count messages with string content (real user prompts)
			if _, ok := msg.Content.(string); ok {
				userIndices = append(userIndices, i)
			} else if arr, ok := msg.Content.([]interface{}); ok {
				// Check if array has text blocks (also a real user prompt)
				for _, item := range arr {
					if m, ok := item.(map[string]interface{}); ok {
						if m["type"] == contentTypeText {
							userIndices = append(userIndices, i)
							break
						}
					}
				}
			}
		}
	}

	// For each user prompt, extract the prompt text, following assistant response, and files
	for idx, userIdx := range userIndices {
		// Determine the range for this prompt's conversation
		endIdx := len(transcript)
		if idx < len(userIndices)-1 {
			endIdx = userIndices[idx+1]
		}

		// Extract prompt text
		prompt := extractUserPromptAt(transcript, userIdx)
		if prompt == "" {
			continue
		}

		// Extract assistant responses and files from this range
		slice := transcript[userIdx:endIdx]
		responses := extractAssistantResponses(slice)
		files := extractModifiedFiles(slice)

		pairs = append(pairs, PromptResponsePair{
			Prompt:    prompt,
			Responses: responses,
			Files:     files,
		})
	}

	return pairs
}

// extractUserPromptAt extracts the user prompt at the given index.
// IDE-injected context tags (like <ide_opened_file>) are stripped from the result.
func extractUserPromptAt(lines []transcriptLine, idx int) string {
	if idx >= len(lines) || lines[idx].Type != transcriptTypeUser {
		return ""
	}

	return transcript.ExtractUserContent(lines[idx].Message)
}

// extractAssistantResponses collects all assistant text blocks from the given transcript slice.
// A single prompt can trigger multiple assistant responses interspersed with tool calls.
func extractAssistantResponses(transcript []transcriptLine) []string {
	var texts []string
	for _, line := range transcript {
		if line.Type == transcriptTypeAssistant {
			var msg assistantMessage
			if err := json.Unmarshal(line.Message, &msg); err != nil {
				continue
			}

			for _, block := range msg.Content {
				if block.Type == contentTypeText && block.Text != "" {
					texts = append(texts, block.Text)
				}
			}
		}
	}
	return texts
}

// extractUserPrompts extracts all user messages from the transcript in order.
// Only considers messages with string content (not tool results).
// IDE-injected context tags (like <ide_opened_file>) are stripped from the results.
func extractUserPrompts(transcript []transcriptLine) []string {
	var prompts []string
	for i := range transcript {
		if transcript[i].Type != transcriptTypeUser {
			continue
		}
		var msg userMessage
		if err := json.Unmarshal(transcript[i].Message, &msg); err != nil {
			continue
		}

		// Handle string content
		if str, ok := msg.Content.(string); ok {
			prompts = append(prompts, textutil.StripIDEContextTags(str))
			continue
		}

		// Handle array content (only if it contains text blocks)
		if arr, ok := msg.Content.([]interface{}); ok {
			var texts []string
			for _, item := range arr {
				if m, ok := item.(map[string]interface{}); ok {
					if m["type"] == contentTypeText {
						if text, ok := m["text"].(string); ok {
							texts = append(texts, text)
						}
					}
				}
			}
			if len(texts) > 0 {
				prompts = append(prompts, textutil.StripIDEContextTags(strings.Join(texts, "\n\n")))
			}
		}
	}
	return prompts
}

// extractLastUserPrompt extracts the last user message from the transcript.
// Only considers messages with string content (not tool results).
// IDE-injected context tags (like <ide_opened_file>) are stripped from the result.
func extractLastUserPrompt(transcript []transcriptLine) string {
	prompts := extractUserPrompts(transcript)
	if len(prompts) == 0 {
		return ""
	}
	return prompts[len(prompts)-1]
}

// findLastUserUUID finds the UUID of the last user message (that has string content)
func findLastUserUUID(transcript []transcriptLine) string {
	for i := len(transcript) - 1; i >= 0; i-- {
		if transcript[i].Type == transcriptTypeUser {
			var msg userMessage
			if err := json.Unmarshal(transcript[i].Message, &msg); err != nil {
				continue
			}
			// Only count messages with string content (not tool results)
			if _, ok := msg.Content.(string); ok {
				return transcript[i].UUID
			}
		}
	}
	return ""
}

// filterTranscriptAfterUUID returns transcript lines after the given UUID
func filterTranscriptAfterUUID(transcript []transcriptLine, uuid string) []transcriptLine {
	if uuid == "" {
		return transcript
	}

	foundIndex := -1
	for i, line := range transcript {
		if line.UUID == uuid {
			foundIndex = i
			break
		}
	}

	if foundIndex == -1 || foundIndex == len(transcript)-1 {
		return transcript
	}

	return transcript[foundIndex+1:]
}

// extractModifiedFiles extracts the list of files modified by tool calls
func extractModifiedFiles(transcript []transcriptLine) []string {
	fileSet := make(map[string]bool)
	var files []string

	for _, line := range transcript {
		if line.Type == transcriptTypeAssistant {
			var msg assistantMessage
			if err := json.Unmarshal(line.Message, &msg); err != nil {
				continue
			}

			for _, block := range msg.Content {
				if block.Type == contentTypeToolUse {
					isModifyTool := false
					for _, name := range claudecode.FileModificationTools {
						if block.Name == name {
							isModifyTool = true
							break
						}
					}

					if isModifyTool {
						var input toolInput
						if err := json.Unmarshal(block.Input, &input); err != nil {
							continue
						}

						file := input.FilePath
						if file == "" {
							file = input.NotebookPath
						}

						if file != "" && !fileSet[file] {
							fileSet[file] = true
							files = append(files, file)
						}
					}
				}
			}
		}
	}

	return files
}

// resolveTranscriptPath determines the correct file path for an agent's session transcript.
// Computes the path dynamically from the current repo location for cross-machine portability.
func resolveTranscriptPath(sessionID string, agent agentpkg.Agent) (string, error) {
	repoRoot, err := paths.WorktreeRoot()
	if err != nil {
		return "", fmt.Errorf("failed to get worktree root: %w", err)
	}

	sessionDir, err := agent.GetSessionDir(repoRoot)
	if err != nil {
		return "", fmt.Errorf("failed to get agent session directory: %w", err)
	}
	return agent.ResolveSessionFile(sessionDir, sessionID), nil
}

// AgentTranscriptPath returns the path to a subagent's transcript file.
// Subagent transcripts are stored as agent-{agentId}.jsonl in the same directory
// as the main transcript.
func AgentTranscriptPath(transcriptDir, agentID string) string {
	return filepath.Join(transcriptDir, fmt.Sprintf("agent-%s.jsonl", agentID))
}

// toolResultBlock represents a tool_result in a user message
type toolResultBlock struct {
	Type      string `json:"type"`
	ToolUseID string `json:"tool_use_id"`
}

// userMessageWithToolResults represents a user message that may contain tool results
type userMessageWithToolResults struct {
	Content []toolResultBlock `json:"content"`
}

// FindCheckpointUUID finds the UUID of the message containing the tool_result
// for the given tool_use_id. This is used to find the checkpoint point for
// transcript truncation when rewinding to a task.
// Returns the UUID and true if found, empty string and false otherwise.
func FindCheckpointUUID(transcript []transcriptLine, toolUseID string) (string, bool) {
	for _, line := range transcript {
		if line.Type != transcriptTypeUser {
			continue
		}

		var msg userMessageWithToolResults
		if err := json.Unmarshal(line.Message, &msg); err != nil {
			continue
		}

		for _, block := range msg.Content {
			if block.Type == "tool_result" && block.ToolUseID == toolUseID {
				return line.UUID, true
			}
		}
	}
	return "", false
}

// TruncateTranscriptAtUUID returns transcript lines up to and including the
// line with the given UUID. If the UUID is not found or is empty, returns
// the entire transcript.
//
//nolint:revive // Exported for testing purposes
func TruncateTranscriptAtUUID(transcript []transcriptLine, uuid string) []transcriptLine {
	if uuid == "" {
		return transcript
	}

	for i, line := range transcript {
		if line.UUID == uuid {
			return transcript[:i+1]
		}
	}

	// UUID not found, return full transcript
	return transcript
}

// writeTranscript writes transcript lines to a file in JSONL format.
func writeTranscript(path string, transcript []transcriptLine) error {
	file, err := os.Create(path) //nolint:gosec // Writing to controlled git metadata path
	if err != nil {
		return fmt.Errorf("failed to create file: %w", err)
	}
	defer func() { _ = file.Close() }()

	for _, line := range transcript {
		data, err := json.Marshal(line)
		if err != nil {
			return fmt.Errorf("failed to marshal line: %w", err)
		}
		if _, err := file.Write(data); err != nil {
			return fmt.Errorf("failed to write line: %w", err)
		}
		if _, err := file.WriteString("\n"); err != nil {
			return fmt.Errorf("failed to write newline: %w", err)
		}
	}

	return nil
}

// TranscriptPosition contains the position information for a transcript file.
type TranscriptPosition struct {
	LastUUID  string // Last non-empty UUID (from user/assistant messages)
	LineCount int    // Total number of lines
}

// GetTranscriptPosition reads a transcript file and returns the last UUID and line count.
// Returns empty position if file doesn't exist or is empty.
// Only considers UUIDs from actual messages (user/assistant), not summary rows which use leafUuid.
func GetTranscriptPosition(path string) (TranscriptPosition, error) {
	if path == "" {
		return TranscriptPosition{}, nil
	}

	file, err := os.Open(path) //nolint:gosec // Reading from controlled transcript path
	if err != nil {
		if os.IsNotExist(err) {
			return TranscriptPosition{}, nil
		}
		return TranscriptPosition{}, fmt.Errorf("failed to open transcript: %w", err)
	}
	defer func() { _ = file.Close() }()

	var pos TranscriptPosition
	reader := bufio.NewReader(file)

	for {
		lineBytes, err := reader.ReadBytes('\n')
		if err != nil && err != io.EOF {
			return TranscriptPosition{}, fmt.Errorf("failed to read transcript: %w", err)
		}

		if len(lineBytes) == 0 {
			if err == io.EOF {
				break
			}
			continue
		}

		pos.LineCount++

		// Parse line to extract UUID (only from user/assistant messages, not summaries)
		var line transcriptLine
		if err := json.Unmarshal(lineBytes, &line); err == nil {
			if line.UUID != "" {
				pos.LastUUID = line.UUID
			}
		}

		if err == io.EOF {
			break
		}
	}

	return pos, nil
}

