308→// canDeleteShadowBranch checks if a shadow branch can be safely deleted.
309→// Returns true if no other sessions (besides excludeSessionID) need this branch.
310→func canDeleteShadowBranch(ctx context.Context, shadowBranch, excludeSessionID string) (bool, error) {
311→	states, err := strategy.ListSessionStates(ctx)
312→	if err != nil {
313→		return false, fmt.Errorf("failed to list session states: %w", err)
314→	}
315→
316→	for _, state := range states {
317→		if state.SessionID == excludeSessionID {
318→			continue
319→		}
320→		otherShadow := checkpoint.ShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
321→		if otherShadow == shadowBranch && state.StepCount > 0 {
322→			return false, nil
323→		}
324→	}
325→
326→	return true, nil
327→}
