 20→// stalenessThreshold is the duration after which an active session is considered stuck.
 21→const stalenessThreshold = 1 * time.Hour
 22→
 23→func newDoctorCmd() *cobra.Command {
 24→	var forceFlag bool
 25→
 26→	cmd := &cobra.Command{
 27→		Use:   "doctor",
 28→		Short: "Fix stuck sessions",
 29→		Long: `Scan for stuck or problematic sessions and offer to fix them.
 30→
 31→A session is considered stuck if:
 32→  - It is in ACTIVE phase with no interaction for over 1 hour
 33→  - It is in ENDED phase with uncondensed checkpoint data on a shadow branch
 34→
 35→For each stuck session, you can choose to:
 36→  - Condense: Save session data to permanent storage (entire/checkpoints/v1 branch)
 37→  - Discard: Remove the session state and shadow branch data
 38→  - Skip: Leave the session as-is
 39→
 40→Use --force to condense all fixable sessions without prompting.  Sessions that can't
 41→be condensed will be discarded.`,
 42→		RunE: func(cmd *cobra.Command, _ []string) error {
 43→			return runSessionsFix(cmd, forceFlag)
 44→		},
 45→	}
 46→
 47→	cmd.Flags().BoolVarP(&forceFlag, "force", "f", false, "Fix all stuck sessions without prompting (condense if possible, otherwise discard)")
 48→
 49→	return cmd
 50→}
 51→
 52→// stuckSession holds a session state along with diagnostic info.
 53→type stuckSession struct {
 54→	State             *strategy.SessionState
 55→	Reason            string
 56→	ShadowBranch      string
 57→	HasShadowBranch   bool
 58→	CheckpointCount   int
 59→	FilesTouchedCount int
 60→}
 61→
 62→func runSessionsFix(cmd *cobra.Command, force bool) error {
 63→	w := cmd.OutOrStdout()
 64→	defer func() { settings.WriteDeprecatedStrategyWarnings(w) }()
 65→
 66→	// Load all session states
 67→	states, err := strategy.ListSessionStates()
 68→	if err != nil {
 69→		return fmt.Errorf("failed to list session states: %w", err)
 70→	}
 71→
 72→	if len(states) == 0 {
 73→		fmt.Fprintln(cmd.OutOrStdout(), "No stuck sessions found.")
 74→		return nil
 75→	}
 76→
 77→	// Open repository to check shadow branches (uses worktree-aware helper)
 78→	repo, err := openRepository()
 79→	if err != nil {
 80→		return fmt.Errorf("failed to open repository: %w", err)
 81→	}
 82→
 83→	// Identify stuck sessions
 84→	now := time.Now()
 85→	var stuck []stuckSession
 86→
 87→	for _, state := range states {
 88→		ss := classifySession(state, repo, now)
 89→		if ss != nil {
 90→			stuck = append(stuck, *ss)
 91→		}
 92→	}
 93→
 94→	if len(stuck) == 0 {
 95→		fmt.Fprintln(cmd.OutOrStdout(), "No stuck sessions found.")
 96→		return nil
 97→	}
 98→
 99→	// Get the current strategy for condense operations
100→	strat := GetStrategy()
101→
102→	fmt.Fprintf(cmd.OutOrStdout(), "Found %d stuck session(s):\n\n", len(stuck))
103→
104→	for _, ss := range stuck {
105→		displayStuckSession(cmd, ss)
106→
107→		if force {
108→			if ss.HasShadowBranch && ss.CheckpointCount > 0 {
109→				if err := strat.CondenseSessionByID(ss.State.SessionID); err != nil {
110→					fmt.Fprintf(cmd.ErrOrStderr(), "Warning: failed to condense session %s: %v\n", ss.State.SessionID, err)
111→				} else {
112→					fmt.Fprintf(cmd.OutOrStdout(), "  -> Condensed session %s\n\n", ss.State.SessionID)
113→				}
114→			} else {
115→				// Discard if we can't condense
116→				if err := discardSession(ss, repo, cmd.ErrOrStderr()); err != nil {
117→					fmt.Fprintf(cmd.ErrOrStderr(), "Warning: failed to discard session %s: %v\n", ss.State.SessionID, err)
118→				} else {
119→					fmt.Fprintf(cmd.OutOrStdout(), "  -> Discarded session %s\n\n", ss.State.SessionID)
120→				}
121→			}
122→			continue
123→		}
124→
125→		// Interactive: prompt for action
126→		action, err := promptSessionAction(ss)
127→		if err != nil {
128→			if errors.Is(err, huh.ErrUserAborted) {
129→				return nil
130→			}
131→			return fmt.Errorf("failed to get action: %w", err)
132→		}
133→
134→		switch action {
135→		case "condense":
136→			if err := strat.CondenseSessionByID(ss.State.SessionID); err != nil {
137→				fmt.Fprintf(cmd.ErrOrStderr(), "Warning: failed to condense session %s: %v\n", ss.State.SessionID, err)
138→			} else {
139→				fmt.Fprintf(cmd.OutOrStdout(), "  -> Condensed session %s\n\n", ss.State.SessionID)
140→			}
141→		case "discard":
142→			if err := discardSession(ss, repo, cmd.ErrOrStderr()); err != nil {
143→				fmt.Fprintf(cmd.ErrOrStderr(), "Warning: failed to discard session %s: %v\n", ss.State.SessionID, err)
144→			} else {
145→				fmt.Fprintf(cmd.OutOrStdout(), "  -> Discarded session %s\n\n", ss.State.SessionID)
146→			}
147→		case "skip":
148→			fmt.Fprintf(cmd.OutOrStdout(), "  -> Skipped\n\n")
149→		}
150→	}
151→
152→	return nil
153→}
