155→// classifySession determines if a session is stuck and returns diagnostic info.
156→// Returns nil if the session is healthy.
157→func classifySession(state *strategy.SessionState, repo *git.Repository, now time.Time) *stuckSession {
158→	// Determine shadow branch info
159→	shadowBranch := checkpoint.ShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
160→	refName := plumbing.NewBranchReferenceName(shadowBranch)
161→	_, refErr := repo.Reference(refName, true)
162→	hasShadowBranch := refErr == nil
163→
164→	switch {
165→	case state.Phase.IsActive():
166→		// Active sessions are stuck if no interaction for over the staleness threshold
167→		isStale := state.LastInteractionTime == nil || now.Sub(*state.LastInteractionTime) > stalenessThreshold
168→		if !isStale {
169→			return nil
170→		}
171→
172→		var reason string
173→		if state.LastInteractionTime != nil {
174→			reason = fmt.Sprintf("active, last interaction %s ago", now.Sub(*state.LastInteractionTime).Truncate(time.Minute))
175→		} else {
176→			reason = "active, no recorded interaction time"
177→		}
178→
179→		return &stuckSession{
180→			State:             state,
181→			Reason:            reason,
182→			ShadowBranch:      shadowBranch,
183→			HasShadowBranch:   hasShadowBranch,
184→			CheckpointCount:   state.StepCount,
185→			FilesTouchedCount: len(state.FilesTouched),
186→		}
187→
188→	case state.Phase == session.PhaseEnded:
189→		// Ended sessions are stuck if they have uncondensed data
190→		if state.StepCount <= 0 || !hasShadowBranch {
191→			return nil
192→		}
193→
194→		return &stuckSession{
195→			State:             state,
196→			Reason:            "ended with uncondensed checkpoint data",
197→			ShadowBranch:      shadowBranch,
198→			HasShadowBranch:   hasShadowBranch,
199→			CheckpointCount:   state.StepCount,
200→			FilesTouchedCount: len(state.FilesTouched),
201→		}
202→
203→	default:
204→		return nil
205→	}
206→}
