208→// displayStuckSession prints diagnostic info for a stuck session.
209→func displayStuckSession(cmd *cobra.Command, ss stuckSession) {
210→	w := cmd.OutOrStdout()
211→
212→	fmt.Fprintf(w, "  Session: %s\n", ss.State.SessionID)
213→	fmt.Fprintf(w, "  Phase:   %s\n", ss.State.Phase)
214→	fmt.Fprintf(w, "  Reason:  %s\n", ss.Reason)
215→
216→	if ss.State.AgentType != "" {
217→		fmt.Fprintf(w, "  Agent:   %s\n", ss.State.AgentType)
218→	}
219→
220→	if ss.State.LastInteractionTime != nil {
221→		fmt.Fprintf(w, "  Last interaction: %s\n", ss.State.LastInteractionTime.Format(time.RFC3339))
222→	}
223→
224→	shadowStatus := "not found"
225→	if ss.HasShadowBranch {
226→		shadowStatus = fmt.Sprintf("exists (%s)", ss.ShadowBranch)
227→	}
228→	fmt.Fprintf(w, "  Shadow branch: %s\n", shadowStatus)
229→	fmt.Fprintf(w, "  Checkpoints: %d, Files touched: %d\n", ss.CheckpointCount, ss.FilesTouchedCount)
230→}
