 68→
 69→	repo, err := git.PlainInit(tmpDir, false)
 70→	if err != nil {
 71→		t.Fatalf("Failed to init repo: %v", err)
 72→	}
 73→
 74→	w, err := repo.Worktree()
 75→	if err != nil {
 76→		t.Fatalf("Failed to get worktree: %v", err)
 77→	}
 78→
 79→	testFile := filepath.Join(tmpDir, "test.txt")
 80→	if err := os.WriteFile(testFile, []byte("test content"), 0o644); err != nil {
 81→		t.Fatalf("Failed to write test file: %v", err)
 82→	}
 83→	if _, err := w.Add("test.txt"); err != nil {
 84→		t.Fatalf("Failed to add test file: %v", err)
 85→	}
 86→
 87→	commit, err := w.Commit("initial commit", &git.CommitOptions{
 88→		Author: &object.Signature{
 89→			Name:  "Test User",
 90→			Email: "test@example.com",
 91→		},
 92→	})
 93→	if err != nil {
 94→		t.Fatalf("Failed to create initial commit: %v", err)
 95→	}
 96→
 97→	if createFeatureBranch {
 98→		featureRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName("feature"), commit)
 99→		if err := repo.Storer.SetReference(featureRef); err != nil {
100→			t.Fatalf("Failed to create feature branch: %v", err)
101→		}
102→	}
103→
104→	// Ensure entire/checkpoints/v1 branch exists
105→	if err := strategy.EnsureMetadataBranch(repo); err != nil {
106→		t.Fatalf("Failed to create metadata branch: %v", err)
107→	}
108→
109→	return repo, w, commit
