269→// createCheckpointOnMetadataBranch creates a checkpoint on the entire/checkpoints/v1 branch.
270→// Returns the checkpoint ID.
271→func createCheckpointOnMetadataBranch(t *testing.T, repo *git.Repository, sessionID string) id.CheckpointID {
272→	t.Helper()
273→
274→	checkpointID := id.MustCheckpointID("abc123def456") // Fixed ID for testing
275→
276→	// Get existing metadata branch or create it
277→	if err := strategy.EnsureMetadataBranch(repo); err != nil {
278→		t.Fatalf("Failed to ensure metadata branch: %v", err)
279→	}
280→
281→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
282→	ref, err := repo.Reference(refName, true)
283→	if err != nil {
284→		t.Fatalf("Failed to get metadata branch ref: %v", err)
285→	}
286→
287→	parentCommit, err := repo.CommitObject(ref.Hash())
288→	if err != nil {
289→		t.Fatalf("Failed to get parent commit: %v", err)
290→	}
291→
292→	// Create metadata content
293→	metadataJSON := fmt.Sprintf(`{
294→  "checkpoint_id": %q,
295→  "session_id": %q,
296→  "created_at": "2025-01-01T00:00:00Z"
297→}`, checkpointID.String(), sessionID)
298→
299→	// Create blob for metadata
300→	blob := repo.Storer.NewEncodedObject()
301→	blob.SetType(plumbing.BlobObject)
302→	writer, err := blob.Writer()
303→	if err != nil {
304→		t.Fatalf("Failed to create blob writer: %v", err)
305→	}
306→	if _, err := writer.Write([]byte(metadataJSON)); err != nil {
307→		t.Fatalf("Failed to write blob: %v", err)
308→	}
309→	if err := writer.Close(); err != nil {
310→		t.Fatalf("Failed to close writer: %v", err)
311→	}
312→	metadataBlobHash, err := repo.Storer.SetEncodedObject(blob)
313→	if err != nil {
314→		t.Fatalf("Failed to store blob: %v", err)
315→	}
316→
317→	// Create session log blob
318→	logBlob := repo.Storer.NewEncodedObject()
319→	logBlob.SetType(plumbing.BlobObject)
320→	logWriter, err := logBlob.Writer()
321→	if err != nil {
322→		t.Fatalf("Failed to create log blob writer: %v", err)
323→	}
324→	if _, err := logWriter.Write([]byte(`{"type":"test"}`)); err != nil {
325→		t.Fatalf("Failed to write log blob: %v", err)
326→	}
327→	if err := logWriter.Close(); err != nil {
328→		t.Fatalf("Failed to close log writer: %v", err)
329→	}
330→	logBlobHash, err := repo.Storer.SetEncodedObject(logBlob)
331→	if err != nil {
332→		t.Fatalf("Failed to store log blob: %v", err)
333→	}
334→
335→	// Build tree structure: <id[:2]>/<id[2:]>/metadata.json
336→	shardedPath := checkpointID.Path()
337→	checkpointIDStr := checkpointID.String()
338→
339→	// Create checkpoint tree with metadata and transcript files
340→	// Entries must be sorted alphabetically
341→	checkpointTree := object.Tree{
342→		Entries: []object.TreeEntry{
343→			{Name: paths.TranscriptFileName, Mode: filemode.Regular, Hash: logBlobHash},
344→			{Name: paths.MetadataFileName, Mode: filemode.Regular, Hash: metadataBlobHash},
345→		},
346→	}
347→	checkpointTreeObj := repo.Storer.NewEncodedObject()
348→	if err := checkpointTree.Encode(checkpointTreeObj); err != nil {
349→		t.Fatalf("Failed to encode checkpoint tree: %v", err)
350→	}
351→	checkpointTreeHash, err := repo.Storer.SetEncodedObject(checkpointTreeObj)
352→	if err != nil {
353→		t.Fatalf("Failed to store checkpoint tree: %v", err)
354→	}
355→
356→	// Create inner shard tree (id[2:])
357→	innerTree := object.Tree{
358→		Entries: []object.TreeEntry{
359→			{Name: checkpointIDStr[2:], Mode: filemode.Dir, Hash: checkpointTreeHash},
360→		},
361→	}
362→	innerTreeObj := repo.Storer.NewEncodedObject()
363→	if err := innerTree.Encode(innerTreeObj); err != nil {
364→		t.Fatalf("Failed to encode inner tree: %v", err)
365→	}
366→	innerTreeHash, err := repo.Storer.SetEncodedObject(innerTreeObj)
367→	if err != nil {
368→		t.Fatalf("Failed to store inner tree: %v", err)
369→	}
370→
371→	// Get existing tree entries from parent
372→	parentTree, err := parentCommit.Tree()
373→	if err != nil {
374→		t.Fatalf("Failed to get parent tree: %v", err)
375→	}
376→
377→	// Build new root tree with shard bucket
378→	var rootEntries []object.TreeEntry
379→	for _, entry := range parentTree.Entries {
380→		if entry.Name != shardedPath[:2] {
381→			rootEntries = append(rootEntries, entry)
382→		}
383→	}
384→	rootEntries = append(rootEntries, object.TreeEntry{
385→		Name: checkpointIDStr[:2],
386→		Mode: filemode.Dir,
387→		Hash: innerTreeHash,
388→	})
389→
390→	rootTree := object.Tree{Entries: rootEntries}
391→	rootTreeObj := repo.Storer.NewEncodedObject()
392→	if err := rootTree.Encode(rootTreeObj); err != nil {
393→		t.Fatalf("Failed to encode root tree: %v", err)
394→	}
395→	rootTreeHash, err := repo.Storer.SetEncodedObject(rootTreeObj)
396→	if err != nil {
397→		t.Fatalf("Failed to store root tree: %v", err)
398→	}
399→
400→	// Create commit on metadata branch
401→	commit := &object.Commit{
402→		Author: object.Signature{
403→			Name:  "Test",
404→			Email: "test@example.com",
405→			When:  parentCommit.Author.When,
406→		},
407→		Committer: object.Signature{
408→			Name:  "Test",
409→			Email: "test@example.com",
410→			When:  parentCommit.Author.When,
411→		},
412→		Message:      "Add checkpoint metadata",
413→		TreeHash:     rootTreeHash,
414→		ParentHashes: []plumbing.Hash{parentCommit.Hash},
415→	}
416→	commitObj := repo.Storer.NewEncodedObject()
417→	if err := commit.Encode(commitObj); err != nil {
418→		t.Fatalf("Failed to encode commit: %v", err)
419→	}
420→	commitHash, err := repo.Storer.SetEncodedObject(commitObj)
421→	if err != nil {
422→		t.Fatalf("Failed to store commit: %v", err)
423→	}
424→
425→	// Update metadata branch ref
426→	newRef := plumbing.NewHashReference(refName, commitHash)
427→	if err := repo.Storer.SetReference(newRef); err != nil {
428→		t.Fatalf("Failed to update metadata branch: %v", err)
429→	}
430→
431→	return checkpointID
432→}
