  54→
  55→			if err := validateSetupFlags(useLocalSettings, useProjectSettings); err != nil {
  56→				return err
  57→			}
  58→
  59→			// Warn if repo has no commits yet
  60→			if repo, err := strategy.OpenRepository(); err == nil && strategy.IsEmptyRepository(repo) {
  61→				fmt.Fprintln(cmd.OutOrStdout(), "Note: This repository has no commits yet. Entire will be configured, but")
  62→				fmt.Fprintln(cmd.OutOrStdout(), "session checkpoints won't work until you create your first commit.")
