1022→// countSessionStates returns the number of active session state files.
1023→func countSessionStates() int {
1024→	store, err := session.NewStateStore()
1025→	if err != nil {
1026→		return 0
1027→	}
1028→	states, err := store.List(context.Background())
1029→	if err != nil {
1030→		return 0
1031→	}
1032→	return len(states)
1033→}
