1035→// countShadowBranches returns the number of shadow branches.
1036→func countShadowBranches() int {
1037→	branches, err := strategy.ListShadowBranches()
1038→	if err != nil {
1039→		return 0
1040→	}
1041→	return len(branches)
1042→}
