1044→// checkEntireDirExists checks if the .entire directory exists.
1045→func checkEntireDirExists() bool {
1046→	entireDirAbs, err := paths.AbsPath(paths.EntireDir)
1047→	if err != nil {
1048→		entireDirAbs = paths.EntireDir
1049→	}
