1054→// removeAgentHooks removes hooks from all agents that support hooks.
1055→func removeAgentHooks(w io.Writer) error {
1056→	var errs []error
1057→	for _, name := range agent.List() {
1058→		ag, err := agent.Get(name)
1059→		if err != nil {
1060→			continue
1061→		}
1062→		hs, ok := ag.(agent.HookSupport)
1063→		if !ok {
1064→			continue
1065→		}
1066→		wasInstalled := hs.AreHooksInstalled()
1067→		if err := hs.UninstallHooks(); err != nil {
1068→			errs = append(errs, err)
1069→		} else if wasInstalled {
1070→			fmt.Fprintf(w, "  Removed %s hooks\n", ag.Type())
1071→		}
1072→	}
1073→	return errors.Join(errs...)
1074→}
1075→
1076→// removeAllSessionStates removes all session state files and the directory.
1077→func removeAllSessionStates() (int, error) {
1078→	store, err := session.NewStateStore()
1079→	if err != nil {
1080→		return 0, fmt.Errorf("failed to create state store: %w", err)
1081→	}
1082→
1083→	// Count states before removing
1084→	states, err := store.List(context.Background())
1085→	if err != nil {
1086→		return 0, fmt.Errorf("failed to list session states: %w", err)
1087→	}
1088→	count := len(states)
1089→
1090→	// Remove the entire directory
1091→	if err := store.RemoveAll(); err != nil {
1092→		return 0, fmt.Errorf("failed to remove session states: %w", err)
1093→	}
1094→
1095→	return count, nil
1096→}
