1098→// removeEntireDirectory removes the .entire directory.
1099→func removeEntireDirectory() error {
1100→	entireDirAbs, err := paths.AbsPath(paths.EntireDir)
1101→	if err != nil {
1102→		entireDirAbs = paths.EntireDir
1103→	}
1104→	if err := os.RemoveAll(entireDirAbs); err != nil {
1105→		return fmt.Errorf("failed to remove .entire directory: %w", err)
1106→	}
1107→	return nil
1108→}
