  44→func TestResolveWorktreeBranch_DetachedHEAD(t *testing.T) {
  45→	dir := t.TempDir()
  46→	if resolved, err := filepath.EvalSymlinks(dir); err == nil {
  47→		dir = resolved
  48→	}
  49→
  50→	repo, err := git.PlainInit(dir, false)
  51→	if err != nil {
  52→		t.Fatalf("git init: %v", err)
  53→	}
  54→
  55→	// Create a commit so we can detach HEAD
  56→	wt, err := repo.Worktree()
  57→	if err != nil {
  58→		t.Fatalf("worktree: %v", err)
  59→	}
  60→	testFile := filepath.Join(dir, "test.txt")
  61→	if err := os.WriteFile(testFile, []byte("hello"), 0o644); err != nil {
  62→		t.Fatalf("write file: %v", err)
  63→	}
  64→	if _, err := wt.Add("test.txt"); err != nil {
  65→		t.Fatalf("add: %v", err)
  66→	}
  67→	hash, err := wt.Commit("initial", &git.CommitOptions{
  68→		Author: &object.Signature{
  69→			Name:  "Test",
  70→			Email: "test@test.com",
  71→			When:  time.Now(),
  72→		},
  73→	})
  74→	if err != nil {
  75→		t.Fatalf("commit: %v", err)
  76→	}
  77→
  78→	// Detach HEAD by writing the raw hash to .git/HEAD
  79→	headPath := filepath.Join(dir, ".git", "HEAD")
  80→	if err := os.WriteFile(headPath, []byte(hash.String()+"\n"), 0o644); err != nil {
  81→		t.Fatalf("write HEAD: %v", err)
  82→	}
  83→
  84→	branch := resolveWorktreeBranch(dir)
  85→	if branch != "HEAD" {
  86→		t.Errorf("resolveWorktreeBranch() = %q, want %q for detached HEAD", branch, "HEAD")
  87→	}
  88→}
