 436→			StartedAt:           now.Add(-2 * time.Hour),
 437→			LastInteractionTime: &recentInteraction,
 438→			FirstPrompt:         "Fix auth bug in login flow",
 439→			AgentType:           agent.AgentType("Claude Code"),
 440→			TokenUsage: &agent.TokenUsage{
