 442→				OutputTokens: 400,
 443→			},
 444→		},
 445→		{
 446→			SessionID:    "def-5678-session",
 447→			WorktreePath: "/Users/test/repo",
 448→			StartedAt:    now.Add(-15 * time.Minute),
 449→			FirstPrompt:  "Add dark mode support for the entire application and all components",
 450→			AgentType:    agent.AgentTypeCursor,
