 471→	writeActiveSessions(&buf, sty)
 472→
 473→	output := buf.String()
 474→
 475→	// Should contain "Active Sessions" in section header
 476→	if !strings.Contains(output, "Active Sessions") {
 477→		t.Errorf("Expected 'Active Sessions' header, got: %s", output)
 478→	}
 479→
 480→	// Should contain agent labels (without brackets in new format)
 481→	if !strings.Contains(output, "Claude Code") {
 482→		t.Errorf("Expected agent label 'Claude Code', got: %s", output)
 483→	}
 484→	if !strings.Contains(output, "Cursor IDE") {
 485→		t.Errorf("Expected agent label 'Cursor', got: %s", output)
 486→	}
 487→	// Session without AgentType should show unknown placeholder
 488→	if !strings.Contains(output, unknownPlaceholder) {
 489→		t.Errorf("Expected '%s' for missing agent type, got: %s", unknownPlaceholder, output)
 490→	}
 491→
 492→	// Should contain truncated session IDs
 493→	if !strings.Contains(output, "abc-123") {
 494→		t.Errorf("Expected truncated session ID 'abc-123', got: %s", output)
 495→	}
 496→
 497→	// Should contain first prompts with chevron
 498→	if !strings.Contains(output, "> \"Fix auth bug in login flow\"") {
 499→		t.Errorf("Expected first prompt with chevron, got: %s", output)
 500→	}
 501→
 502→	// Session without FirstPrompt should NOT show a prompt line
