 504→	for _, line := range lines {
 505→		if strings.Contains(line, "ghi-901") {
 506→			if strings.Contains(line, "\"") {
 507→				t.Errorf("Session without prompt should not show quoted text on first line, got: %s", line)
 508→			}
 509→		}
 510→	}
 511→
 512→	// Should show "active 5m ago" for session with LastInteractionTime that differs from StartedAt
 513→	if !strings.Contains(output, "active 5m ago") {
 514→		t.Errorf("Expected 'active 5m ago' for session with LastInteractionTime, got: %s", output)
 515→	}
 516→
 517→	// Session started 15m ago with no LastInteractionTime should NOT show "active" in stats
 518→	for _, line := range lines {
 519→		if strings.Contains(line, "Cursor IDE") {
 520→			if strings.Contains(line, "active") {
 521→				t.Errorf("Session without LastInteractionTime should not show 'active', got: %s", line)
 522→			}
 523→		}
 524→	}
 525→
 526→	// Should contain per-session token counts
 527→	if !strings.Contains(output, "tokens 1.2k") {
 528→		t.Errorf("Expected per-session 'tokens 1.2k' for first session (800+400), got: %s", output)
 529→	}
 530→
 531→	// Should contain aggregate footer with session count (no total tokens in footer)
 532→	if !strings.Contains(output, "3 sessions") {
 533→		t.Errorf("Expected aggregate '3 sessions' in footer, got: %s", output)
 534→	}
 535→
 536→	// Should NOT contain phase indicators (removed)
 537→	if strings.Contains(output, "● active") || strings.Contains(output, "● idle") || strings.Contains(output, "● ended") {
 538→		t.Errorf("Output should not contain phase indicators, got: %s", output)
 539→	}
 540→
 541→	// Should NOT contain file counts (removed)
 542→	if strings.Contains(output, "files ") {
 543→		t.Errorf("Output should not contain file counts, got: %s", output)
 544→	}
 545→}
