func TestWriteSession_RoundTrip(t *testing.T) {
	t.Parallel()
	tmpDir := t.TempDir()
	transcriptPath := writeSampleTranscript(t, tmpDir)

	ag := &CursorAgent{}

	// Read
	input := &agent.HookInput{
		SessionID:  "roundtrip-session",
