 65→// setupResumeTestRepo creates a test repository with an initial commit and optional feature branch.
 66→// Returns the repository, worktree, and commit hash. The caller should use t.Chdir(tmpDir).
 67→func setupResumeTestRepo(t *testing.T, tmpDir string, createFeatureBranch bool) (*git.Repository, *git.Worktree, plumbing.Hash) {
 68→	t.Helper()
 69→
 70→	repo, err := git.PlainInit(tmpDir, false)
 71→	if err != nil {
 72→		t.Fatalf("Failed to init repo: %v", err)
 73→	}
 74→
 75→	w, err := repo.Worktree()
 76→	if err != nil {
 77→		t.Fatalf("Failed to get worktree: %v", err)
 78→	}
 79→
 80→	testFile := filepath.Join(tmpDir, "test.txt")
 81→	if err := os.WriteFile(testFile, []byte("test content"), 0o644); err != nil {
 82→		t.Fatalf("Failed to write test file: %v", err)
 83→	}
 84→	if _, err := w.Add("test.txt"); err != nil {
 85→		t.Fatalf("Failed to add test file: %v", err)
 86→	}
 87→
 88→	commit, err := w.Commit("initial commit", &git.CommitOptions{
 89→		Author: &object.Signature{
 90→			Name:  "Test User",
 91→			Email: "test@example.com",
 92→		},
 93→	})
 94→	if err != nil {
 95→		t.Fatalf("Failed to create initial commit: %v", err)
 96→	}
 97→
 98→	if createFeatureBranch {
 99→		featureRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName("feature"), commit)
100→		if err := repo.Storer.SetReference(featureRef); err != nil {
101→			t.Fatalf("Failed to create feature branch: %v", err)
102→		}
103→	}
104→
105→	// Ensure entire/checkpoints/v1 branch exists
106→	if err := strategy.EnsureMetadataBranch(repo); err != nil {
107→		t.Fatalf("Failed to create metadata branch: %v", err)
108→	}
109→
110→	return repo, w, commit
111→}
