270→// createCheckpointOnMetadataBranch creates a checkpoint on the entire/checkpoints/v1 branch.
271→// Returns the checkpoint ID.
272→func createCheckpointOnMetadataBranch(t *testing.T, repo *git.Repository, sessionID string) id.CheckpointID {
273→	t.Helper()
274→
275→	checkpointID := id.MustCheckpointID("abc123def456") // Fixed ID for testing
276→
277→	// Get existing metadata branch or create it
278→	if err := strategy.EnsureMetadataBranch(repo); err != nil {
279→		t.Fatalf("Failed to ensure metadata branch: %v", err)
280→	}
281→
282→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
283→	ref, err := repo.Reference(refName, true)
284→	if err != nil {
285→		t.Fatalf("Failed to get metadata branch ref: %v", err)
286→	}
287→
288→	parentCommit, err := repo.CommitObject(ref.Hash())
289→	if err != nil {
290→		t.Fatalf("Failed to get parent commit: %v", err)
291→	}
292→
293→	// Create metadata content
294→	metadataJSON := fmt.Sprintf(`{
295→  "checkpoint_id": %q,
296→  "session_id": %q,
297→  "created_at": "2025-01-01T00:00:00Z"
298→}`, checkpointID.String(), sessionID)
299→
300→	// Create blob for metadata
301→	blob := repo.Storer.NewEncodedObject()
302→	blob.SetType(plumbing.BlobObject)
303→	writer, err := blob.Writer()
304→	if err != nil {
305→		t.Fatalf("Failed to create blob writer: %v", err)
306→	}
307→	if _, err := writer.Write([]byte(metadataJSON)); err != nil {
308→		t.Fatalf("Failed to write blob: %v", err)
309→	}
310→	if err := writer.Close(); err != nil {
311→		t.Fatalf("Failed to close writer: %v", err)
312→	}
313→	metadataBlobHash, err := repo.Storer.SetEncodedObject(blob)
314→	if err != nil {
315→		t.Fatalf("Failed to store blob: %v", err)
316→	}
317→
318→	// Create session log blob
319→	logBlob := repo.Storer.NewEncodedObject()
320→	logBlob.SetType(plumbing.BlobObject)
321→	logWriter, err := logBlob.Writer()
322→	if err != nil {
323→		t.Fatalf("Failed to create log blob writer: %v", err)
324→	}
325→	if _, err := logWriter.Write([]byte(`{"type":"test"}`)); err != nil {
326→		t.Fatalf("Failed to write log blob: %v", err)
327→	}
328→	if err := logWriter.Close(); err != nil {
329→		t.Fatalf("Failed to close log writer: %v", err)
330→	}
331→	logBlobHash, err := repo.Storer.SetEncodedObject(logBlob)
332→	if err != nil {
333→		t.Fatalf("Failed to store log blob: %v", err)
334→	}
335→
336→	// Build tree structure: <id[:2]>/<id[2:]>/metadata.json
337→	shardedPath := checkpointID.Path()
338→	checkpointIDStr := checkpointID.String()
339→
340→	// Create checkpoint tree with metadata and transcript files
341→	// Entries must be sorted alphabetically
342→	checkpointTree := object.Tree{
343→		Entries: []object.TreeEntry{
344→			{Name: paths.TranscriptFileName, Mode: filemode.Regular, Hash: logBlobHash},
345→			{Name: paths.MetadataFileName, Mode: filemode.Regular, Hash: metadataBlobHash},
346→		},
347→	}
348→	checkpointTreeObj := repo.Storer.NewEncodedObject()
349→	if err := checkpointTree.Encode(checkpointTreeObj); err != nil {
350→		t.Fatalf("Failed to encode checkpoint tree: %v", err)
351→	}
352→	checkpointTreeHash, err := repo.Storer.SetEncodedObject(checkpointTreeObj)
353→	if err != nil {
354→		t.Fatalf("Failed to store checkpoint tree: %v", err)
355→	}
356→
357→	// Create inner shard tree (id[2:])
358→	innerTree := object.Tree{
359→		Entries: []object.TreeEntry{
360→			{Name: checkpointIDStr[2:], Mode: filemode.Dir, Hash: checkpointTreeHash},
361→		},
362→	}
363→	innerTreeObj := repo.Storer.NewEncodedObject()
364→	if err := innerTree.Encode(innerTreeObj); err != nil {
365→		t.Fatalf("Failed to encode inner tree: %v", err)
366→	}
367→	innerTreeHash, err := repo.Storer.SetEncodedObject(innerTreeObj)
368→	if err != nil {
369→		t.Fatalf("Failed to store inner tree: %v", err)
370→	}
371→
372→	// Get existing tree entries from parent
373→	parentTree, err := parentCommit.Tree()
374→	if err != nil {
375→		t.Fatalf("Failed to get parent tree: %v", err)
376→	}
377→
378→	// Build new root tree with shard bucket
379→	var rootEntries []object.TreeEntry
380→	for _, entry := range parentTree.Entries {
381→		if entry.Name != shardedPath[:2] {
382→			rootEntries = append(rootEntries, entry)
383→		}
384→	}
385→	rootEntries = append(rootEntries, object.TreeEntry{
386→		Name: checkpointIDStr[:2],
387→		Mode: filemode.Dir,
388→		Hash: innerTreeHash,
389→	})
390→
391→	rootTree := object.Tree{Entries: rootEntries}
392→	rootTreeObj := repo.Storer.NewEncodedObject()
393→	if err := rootTree.Encode(rootTreeObj); err != nil {
394→		t.Fatalf("Failed to encode root tree: %v", err)
395→	}
396→	rootTreeHash, err := repo.Storer.SetEncodedObject(rootTreeObj)
397→	if err != nil {
398→		t.Fatalf("Failed to store root tree: %v", err)
399→	}
400→
401→	// Create commit on metadata branch
402→	commit := &object.Commit{
403→		Author: object.Signature{
404→			Name:  "Test",
405→			Email: "test@example.com",
406→			When:  parentCommit.Author.When,
407→		},
408→		Committer: object.Signature{
409→			Name:  "Test",
410→			Email: "test@example.com",
411→			When:  parentCommit.Author.When,
412→		},
413→		Message:      "Add checkpoint metadata",
414→		TreeHash:     rootTreeHash,
415→		ParentHashes: []plumbing.Hash{parentCommit.Hash},
416→	}
417→	commitObj := repo.Storer.NewEncodedObject()
418→	if err := commit.Encode(commitObj); err != nil {
419→		t.Fatalf("Failed to encode commit: %v", err)
420→	}
421→	commitHash, err := repo.Storer.SetEncodedObject(commitObj)
422→	if err != nil {
423→		t.Fatalf("Failed to store commit: %v", err)
424→	}
425→
426→	// Update metadata branch ref
427→	newRef := plumbing.NewHashReference(refName, commitHash)
428→	if err := repo.Storer.SetReference(newRef); err != nil {
429→		t.Fatalf("Failed to update metadata branch: %v", err)
430→	}
431→
432→	return checkpointID
433→}
